زته احلشيش‬\n ‫‪121‬‬       ‫بقصد التعاطي وتعاطيه له ومحاولة الهروب من‬        ‫حيازة‬    ‫‪17‬‬\n                 ‫رجال األمن وتستره على املصدر‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪131‬‬      ‫بقصد البيع وشروعه يف البيع وتعاطيه للحشيش‬         ‫حيازة‬    ‫‪18‬‬\n               ‫ومحاولة الهروب من رجال األمن‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته الهيروين‬\n ‫‪138‬‬                                                        ‫حيازة‬    ‫‪19‬‬\n                          ‫بقصد التعاطي‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته األفيون‬\n ‫‪143‬‬                                                        ‫حيازة‬    ‫‪20‬‬\n                     ‫بقصد التعاطي وتعاطيه له‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪148‬‬                                                        ‫حيازة‬    ‫‪21‬‬\n                   ‫بقصد االستعمال الشخصي‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليهم لالشتراك يف‬\n         ‫حيازة احلشيش بقصد التعاطي وتعاطيهم له وتعاطي‬\n ‫‪155‬‬                                                        ‫حيازة‬    ‫‪22‬‬\n          ‫أحدهم احلبوب احملظورة وقيادته للسيارة حتت‬\n                            ‫تأثيرها‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلبوب‬\n ‫‪167‬‬     ‫احملظورة بقصد التعاطي والعتدائه على رجل األمن‬      ‫حيازة‬    ‫‪23‬‬\n                 ‫وإقامة عالقة مع فتاة واصطحابها‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه حليازته القات بقصد‬\n ‫‪176‬‬      ‫الترويج والتعاطي واصطحابه المرأتني ال متتان له‬    ‫حيازة‬    ‫‪24‬‬\n                             ‫بصلة شرعية‬\n\f‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهم حليازة الثاني حبوب‬\n          ‫اإلمفيتامني بقصد التعاطي والترويج وتعاطيه لها‬\n ‫‪182‬‬      ‫وحيازة الثالث للمسكر بقصد الشرب وشربه له‬           ‫حيازة‬    ‫‪25‬‬\n         ‫ومحاولة الهروب من رجال األمن ومحاولة مقاومتهم‬\n                          ‫وشرب املسكر‬\n\n\n            ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪195‬‬     ‫بقصد التعاطي وتعاطيه له وقيادة السيارة حتت تأثير‬    ‫حيازة‬    ‫‪26‬‬\n            ‫احلشيش ومقاومته للفرقة القابضة وهروبه منها‬\n\n\n            ‫دعوى عامة بتعزير املدعى عليه حليازته حبوب‬\n ‫‪208‬‬       ‫اإلمفيتامني بقصد التعاطي وتعاطيه لها وقيادته‬      ‫حيازة‬    ‫‪27‬‬\n                        ‫السيارة حتت تأثيرها‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه بالتستر على حائز‬\n ‫‪214‬‬                                                         ‫حيازة‬    ‫‪28‬‬\n                             ‫مخدرات‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪221‬‬                                                         ‫حيازة‬    ‫‪29‬‬\n           ‫وحبوب الترامادول بقصد التعاطي وتعاطيه لها‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته قطعة من‬\n ‫‪227‬‬                                                         ‫حيازة‬    ‫‪30‬‬\n            ‫احلشيش لقصد االستعمال واستعماله احلشيش‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪232‬‬                                                         ‫حيازة‬    ‫‪31‬‬\n              ‫لالستعمال الشخصي واستعماله له‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهما حليازتهما احلشيش‬\n ‫‪240‬‬                                                         ‫حيازة‬    ‫‪32‬‬\n         ‫وحيازة أحدهما حلبة من اإلمفيتامني بقصد التعاطي‬\n\f‫الصفحة‬                       ‫املوضوع‬                         ‫التصنيف‬   ‫م‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليهما حليازة احلشيش‬\n           ‫وحبوب الكلونازيبام احملظورة بقصد التعاطي‬\n ‫‪246‬‬                                                          ‫حيازة‬    ‫‪33‬‬\n            ‫والترويج وتعاطيهما للحشيش وحيازة أحدهما‬\n                ‫لقارورة مسكر وشربه للمسكر‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪260‬‬      ‫بقصد االجتار والتعاطي وشروعه يف البيع وتعاطي‬        ‫حيازة‬    ‫‪34‬‬\n                             ‫احلشيش‬\n\n\n          ‫الشمة‬\n            ‫ّ‬    ‫دعوى عامة بتعزير املدعى عليه لبيعه مادة‬\n ‫‪274‬‬                                                          ‫حيازة‬    ‫‪35‬‬\n         ‫بقصد الترويج وحيازة ‪ 73‬كيلو منها بقصد الترويج‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪280‬‬                                                          ‫حيازة‬    ‫‪36‬‬\n                   ‫بقصد التعاطي وتعاطيه له‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪287‬‬                                                          ‫حيازة‬    ‫‪37‬‬\n                   ‫لقصد التعاطي وتعاطيه له‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪295‬‬     ‫واحلبوب احملظورة بقصد الترويج واالجتار والتعاطي‬      ‫حيازة‬    ‫‪38‬‬\n                       ‫وتستره على املصدر‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليه ( مقيم) بتلقي احلبوب‬\n ‫‪311‬‬       ‫احملظورة (الترامادول وتامول إكس وديبريبان)‬         ‫حيازة‬    ‫‪39‬‬\n                          ‫بقصد استعمالها‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه (مقيم بطريقة غير‬\n ‫‪317‬‬     ‫نظامية) حليازته ‪ 163‬حبة من احلبوب احملظورة بقصد‬      ‫حيازة‬    ‫‪40‬‬\n                   ‫الترويج والتعاطي وتعاطيه لها‬\n\f‫الصفحة‬                     ‫املوضوع‬                      ‫التصنيف‬   ‫م‬\n\n\n          ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n ‫‪324‬‬     ‫وحبة من احلبوب احملظورة بقصد الترويج وتستره‬     ‫حيازة‬    ‫‪41‬‬\n              ‫على املصدر وهروبه من رجال األمن‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":324,"source_page_end":339,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6d06e08ef4d8c638d096ee0749b5edb5b5e1a74f9fb1d1102bd8a52423f6f9a0","normalized_text_hash":"10f4e47405e111a3cbd525f85ec9bed8a1c3e20607462c509cd14bfafe2b98ce","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p324-33374012"},{"id":"d7461711-acd9-519f-8811-864d95848891","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع أرض -مطالبة بإعادة ثمن مبيع -بيع ما ال ميلك -املدعى عليهما متضامنن -مباشرة العقد والتفاوض موجبة للضمان - صحة ضمان عهدة املبيع -إلزام املدعى عليهما بتسليم ثمن املبيع.","document_number":"34277805","case_number":"32399029","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/24","year":"1434","subject":"بيع أرض -مطالبة بإعادة ثمن مبيع -بيع ما ال ميلك -املدعى عليهما متضامنن -مباشرة العقد والتفاوض موجبة للضمان - صحة ضمان عهدة املبيع -إلزام املدعى عليهما بتسليم ثمن املبيع.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"    ‫تاريخه‪1434/7/24 :‬هـ‬\n                    ‫ُ‬                  ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34277805 :‬‬\n                        ‫َر ْق ُم الدعوى‪32399029 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34325465‬تاريخه‪1434/9/24 :‬هـ‬\n\n\n    ‫بيــع أرض ‪ -‬مطالبــة بإعــادة ثمــن مبيــع ‪ -‬بيــع مــا ال ميلــك ‪ -‬املدعــى‬\n    ‫عليهمــا متضامنــن ‪ -‬مباشــرة العقــد والتفــاوض موجبــة للضمــان ‪-‬‬\n    ‫صحــة ضمــان عهــدة املبيــع ‪ -‬إلــزام املدعــى عليهما بتســليم ثمــن املبيع‪.‬‬\n\n\n\n\n    ‫جــاء يف الــروض املربــع ‪( :103/5‬ويصــح ضمــان عهــدة مبيــع بــأن يضمــن‬\n                                                 ‫الثمــن إذا اســتحق املبيــع) ‪.‬‬\n\n\n\n\n    ‫ادعــى املدعــي أصالــة ووكالــة ضــد املدعــى عليهمــا الغائبــن بأنــه‬\n    ‫اشــترى مــن املدعــى عليهمــا ســبع وعشــرين قطعــة أرض علــى طريــق ‪...‬‬\n    ‫تقــع يف حــي املخطــط ‪ ...‬وإجمالــي مســاحة كل قطعــة خمســمائة متــر‬\n    ‫مربــع كمــا أن موكلــه قــد اشــترى قطعتــن يف نفــس املخطــط وقد غره‬\n    ‫وغــر موكلــه املدعــى عليهمــا وقــت الشــراء وقــاال إن املخطــط معتمــد‬\n    ‫مــن األمانــة مبوجــب صــك عــام وســوف يتــم اإلفــراغ بعــد خمســة عشــر‬\n    ‫يوم ـ ًا مــن تاريــخ الشــراء ثــم اتضــح أن املخطــط كامــا ملــك للدولــة‬\n    ‫ومبــا أن املدعــى عليهمــا متضامنــن قــد اســتلما منــه أربعــة وتســعني‬\n    ‫ألف ـ ًا وخمســمائة ريــال ومــن موكلــه خمســة عشــر ألــف ريــال يطلــب‬\n    ‫إلزامهمــا بإعــادة املبلغــن هكــذا ادعــى ‪ ،‬لــم يحضــر املدعــى عليهمــا‬\n‫‪5‬‬\n\f‫رغــم تبلغهمــا باملوعــد فتــم ســماع الدعــوى غيابي ـ ًا ‪ -‬يف جلســة تاليــة‬\n‫حضــر املدعــي واملدعــى عليــه وكالــة وأجــاب بــأن موكليــه حضــرا‬\n‫كشــاهدين والعقــد كان بــن املدعــي وبــن شــخص ‪ ،‬ذكــر اســمه‬\n‫‪ ،‬ويطلــب إدخالــه يف الدعــوى ‪ ،‬أحضــر املدعــي بينــة وهمــا شــاهدان‬\n‫شــهدا طبــق دعــواه ‪ ،‬أجــاب املدعــى عليــه عــن الشــهادة بأنهــا متعارضــة‬\n‫فيمــا بينهــا يف ذكــر عــدد القطــع كمــا أن الشــاهدين خــاف الذيــن‬\n‫أحضرهمــا املدعــي للشــهادة يف احلكــم املنقــوض ‪ ،‬أجــاب املدعــي بــأن‬\n‫املبايعــة حصلــت مــن ســبع ســنوات واملهــم هــو أنهمــا اســتلما املبلــغ بغــض‬\n‫النظــر عــن عــدد القطــع وأن الشــاهدين املذكــوران يف صــك احلكــم‬\n‫املنقــوض كانــا يف املوقــع‪ ،‬ولــم يكونــا معــه يف الســيارة ‪ ،‬ومبــا أن‬\n‫املدعــي أصالــة ووكالــة أحضــر بينــة تشــهد طبــق دعــواه ‪ ،‬وهاتــان‬\n‫الشــهادتان تــدل علــى أن املدعــى عليهمــا تفاوضــا مــع املدعــي أصالــة‬\n‫وموكلــه‪ ،‬وقــد صــرح أحدهمــا بأنــه ضامــن ملــال املدعــن حــال وجــود‬\n‫مشــكلة علــى العقــارات محــل البيــع‪ ،‬وهــذا يــدل علــى أنهمــا متضامنان‬\n‫يف هــذا العمــل ومســؤوالن عنــه فإســتالم أحدهمــا كإســتالمهما معــا‪،‬‬\n‫وضمــان الــدرك املعــروف بضمــان العهــدة بــأن يضمــن ثمــن املبيــع إن‬\n‫ظهــر مســتحقا كمــا هــو مقــرر فقهــا‪ ،‬قــال يف الــروض املربــع ‪:103/5‬‬\n‫(ويصــح ضمــان عهــدة مبيــع بــأن يضمن الثمن إذا اســتحق املبيع)‪ ،‬كما‬\n‫أنهمــا قــد باشــرا العقــد والتفــاوض وهــذا موجــب لضمانهمــا بإعــادة مــا‬\n‫اســتلماه‪ ،‬يضــاف لذلــك خلـ ّـو العقــد مــن كتابــة قيمــة املبيــع يف تســعة‬\n‫وعشــرين عقــدا يــدلّ تبييتهــم للكــذب واملراوغــة‪ ،‬ويضــاف أيضــا‬\n‫أن شــهادة املدعــى عليهمــا لــكل مــن طلــب منهمــا الشــهادة يف املوقــع‬\n‫أمــر يدعــو للتهمــة ويقــوي دعــوى املدعــي أصالــة ووكالــة جتاههمــا ‪-‬‬\n\n\n                                                                                     ‫‪6‬‬\n\f    ‫ملــا تقــدم صــدر احلكــم بإلــزام املدعــى عليهمــا متضامنــن أن يس ـلّما‬\n    ‫للمدعــي أصالــة‪ :‬مبلغــا قــدره‪ :‬أربعــة وتســعون ألف ـ ًا وخمســمائة ريــال‪،‬‬\n    ‫ويس ـلّما ملوكلــه‪ :‬مبلغــا قــدره‪ :‬خمســة عشــر ألــف ريــال ‪ -‬قنــع املدعــي‬\n    ‫أصالــة ووكالــة باحلكــم‪ ،‬أمــا املدعــى عليــه وكالــة فاعتــرض بالئحــة‬\n    ‫‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة الرابعــة مبحكمــة االســتئناف‬\n                                                    ‫مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n    ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فلــدي أنــا (‪ )....‬القاضــي باحملكمــة العامــة‬\n    ‫بجــدة‪ ،‬وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n    ‫العامــة مبحافظــة جــدة املســاعد برقــم‪ 32399029 :‬وتاريــخ‪:‬‬\n    ‫‪1432/09/08‬ه ـ املقيــدة باحملكمــة برقــم‪ 32966385 :‬وتاريــخ‪:‬‬\n    ‫‪1432/08/01‬ه ـ واملنقوضــة مــن محكمــة االســتئناف بالقــرار رقــم‪:‬‬\n    ‫‪/4/17‬ن يف‪1432/7/19 :‬ه ـ وبعــد عــدة جلســات ففــي يــوم الثالثــاء‬\n    ‫املوافــق‪1433/10/17 :‬ه ـ حضــر‪ .... :‬ســعودي اجلنســية مبوجــب الهويــة‬\n    ‫الوطنيــة رقــم ‪....‬باالصالــة عــن نفســه وبالوكالــة عــن ‪....‬مبوجــب‬\n    ‫الوكالــة الصــادر مــن كتابــة عــدل الثانيــة بغــرب مكــة املكرمــة برقم‬\n    ‫‪ 3373439‬يف ‪1433/2/9‬ه ـ ولــم يحضــر املدعــى عليهمــا وال مــن ينــوب‬\n    ‫عنهمــا مــع تبلــغ وكيلهمــا لشــخصه كمــا هــو مــدون يف ضبــط اجللســة‬\n    ‫الســابقة ونظــرا لكــون الدعــوى غيــر محــررة حتريــرا واضحــا قــررت‬\n    ‫إعــادة ســماع الدعــوى فادعــى املدعــي قائــا‪ :‬اننــي قــد اشــتريت مــن‬\n    ‫املدعــى عليهمــا ســبع وعشــرين قطعــة ارض علــى طريــق ‪ ......‬وهــي كمــا‬\n    ‫يلــي قطعــة رقــم ‪ 381‬و‪ 382‬و‪ 383‬و‪ 384‬و‪ 385‬و‪ 386‬و‪ 387‬و‪ 389‬و‪390‬‬\n\n‫‪7‬‬\n\f‫و‪ 391‬و‪ 393 392‬و‪ 368‬و‪ 369‬و‪ 370‬و‪ 371‬و ‪ 372‬و‪ 373‬و‪ 374‬و‪375‬‬\n‫و‪ 376‬و‪ 377‬و‪ 378‬و‪ 379‬و‪ 367‬و‪ 366‬وكل واحــدة مــن هــذه القطــع‬\n‫تقــع يف حــي ‪....‬واجمالــي مســاحة كل قطعــة خمســمائة متــر مربــع‬\n‫كمــا ان موكلــي قــد اشــترى قطعــة رقــم ‪ 393‬و‪ 394‬الواقعــة يف‬\n‫طريق‪....‬بحــي ‪....‬مســاحة األولــى منهمــا خمســمائة متــر مربــع ومســاحة‬\n‫الثانيــة ســبعمائة متــر مربــع بقيمــة ســبعة االف وخمســمائة ريــال لــكل‬\n‫قطعــة قــد غرنــي وغــر موكلــي املدعــى عليهمــا وقــت الشــراء وقــاال ان‬\n‫املخطــط معتمــد مــن االمانــة مبوجــب صــك عــام وســوف يتــم االفــراغ بعد‬\n‫خمســة عشــر يومــا مــن تاريــخ الشــراء ثــم اتضــح لنــا ان املخطــط كامــا‬\n‫مبــا فيــه العقــارات املشــار اليهــا اعــاه ملــك للدولــة ومبــا ان املدعــى‬\n‫عليهمــا متضامنــن قــد اســتلما منــي اربعــة وتســعني الف ـ ًا وخمســمائة‬\n‫ريــال ومــن موكلــي خمســة عشــر الــف ريــال فانــي اطلــب الزامهمــا‬\n‫باعــادة اربعــة وتســعني الــف وخمســمائة ريــال لــي وخمســة عشــر الــف‬\n‫ريــال ملوكلــي هكــذا ادعــى وبســؤاله عــن حــدود واطــوال كل قطعــة‬\n‫اجــاب قائــا اننــي ال اعــرف حدودهــا وال اطوالهــا وبســؤال املدعــي عــن‬\n‫بينتــه اجــاب قائــا اطلــب مهلــة الحضارهــا هكــذا اجــاب ويف يــوم‬\n‫الثالثــاء املوافــق‪1434/03/17 :‬ه ـ حضــر املدعــي ‪....‬املثبــت حضــوره يف‬\n‫جلســة ســابقة وحضــر حلضــوره ‪....‬ســعودي اجلنســية مبوجــب الهويــة‬\n‫الوطنيــة رقــم ‪....‬الوكيــل ‪....‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫عــدل محافظــة بلجرشــي رقــم ‪ 37‬يف ‪1430/6/22‬ه ـ واملخــول لــه فيهــا‬\n‫حــق االنــكار والتحكيــم وطلــب اليمــن والوكيــل عــن ‪....‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كاتــب عــدل الهيئــة العامــة لالســتثمار رقــم ‪27‬‬\n‫يف ‪1429/11/24‬ه ـ واملخــول لــه فيهــا حــق املرافعــة واملدافعــة وطلــب‬\n\n\n                                                                                   ‫‪8‬‬\n\f    ‫اليمــن والصلــح وبعــرض دعــوى املدعــي علــى املدعــى عليــه وكالــة‬\n    ‫أجــاب قائــا ان موكلــي حضــرا كشــاهدين والعقــد كان بــن املدعــي‬\n    ‫وبــن ‪ ....‬اطلــب ادخالــه يف الدعــوى هكــذا أجــاب وبســؤال املدعــي عــن‬\n    ‫بينتــه أحضــر للشــهادة وادائهــا كال مــن ‪ ....‬ســعودي اجلنســية مبوجــب‬\n    ‫الهويــة الوطنيــة رقــم ‪....‬مــن مواليــد عــام ‪1409‬ه ـ ويعمــل يف التجــارة‬\n    ‫واملدعــي زوج ألختــه واملدعــي اآلخــر ليــس لــه قرابــة بــه حســب افادتــه‬\n    ‫وبســؤاله عمــا لديــه شــهد قائــا‪( :‬أشــهد هلل أننــي كنــت حاضــرا يف‬\n    ‫مخطــط مقابــل محطــة‪....‬وكان معنــا ‪....‬و‪....‬و‪....‬و‪....‬ومعنــا آخــرون‬\n    ‫وكان ‪....‬و‪....‬يتفاوضــون مــع ‪....‬و‪ ....‬علــى ‪ 27‬قطعــة أرض يف املخطــط‬\n    ‫الذهبــي ثــم قــال ‪....‬ل‪ ....‬وا‪ ....‬هــذه األراضــي موثقــة وليــس فيها مشــكلة‬\n    ‫وهــي باســم ‪ ،...‬وسـلّم لــي يــا ‪....‬اآلن كامــل مبلــغ القطــع وقــدره‪ :‬أربعــة‬\n    ‫وتســعون ألــف وخمســمائة ريــال وأنــت يــا ‪....‬ســلم لــي مبلــغ القطعتــن‬\n    ‫يلكــم) وبعدهــا يكــون اإلفــراغ‪ ،‬وبعدهــا رأيــت ‪....‬يســلم ألحــد‬   ‫وأنــا (قِ ِب ُ‬\n    ‫املدعــى عليهــا إمــا ‪....‬وإمــا ‪....‬مبلغــا قــدره‪ :‬أربعــة وتســعون ألــف ريــال‬\n    ‫كمــا رأيــت ‪....‬يســلم ألحــد املدعــى عليهمــا مبلغــا قــدره‪ :‬خمســة عشــر‬\n    ‫ألــف)‪ ،‬هكــذا شــهد‪ .‬وبســؤاله عــن املبالــغ أجــاب قائــا‪ :‬إننــي كنــت‬\n    ‫راكبــا مــع املدعــن يف الســيارة ملــا كانــا قادمــن للموقــع وبصحبتنــا ‪....‬‬\n    ‫فقــط أربعــة أشــخاص وقمــت بعـ ِّـد املبلــغ عشــر مــرات‪ ،‬هكــذا أجــاب‪.‬‬\n    ‫وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه وكالــة أجــاب قائــا‪:‬‬\n    ‫أطلــب مهلــة لإلجابــة عنهــا‪ ،‬هكــذا أجــاب‪ .‬كمــا احضــر للشــهادة ‪.....‬‬\n    ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪....‬مــن مواليــد عــام‬\n    ‫‪1407‬ه ـ ويعمــل عســكري واملدعــي زوج ألختــه واملدعــي اآلخــر ليــس له‬\n    ‫قرابــة بــه حســب افادتــه وبســؤاله عمــا لديــه شــهد قائــا‪( :‬أشــهد هلل‬\n\n\n‫‪9‬‬\n\f‫أننــي كنــت مــع ‪....‬قبــل ســبع ســنوات تقريبــا يف ســيارته فتوقــف عــن‬\n‫البنــك ‪....‬يف ‪ ...‬ونزلــت معــه للبنــك وطلــب مــن موظــف البنــك أن يســحب‬\n‫من حســابه مبلغا قدره‪ :‬أربعة وتســعون ألف وخمســمائة ريال فاســتلمها‬\n‫مــن موظــف البنــك وبعدهــا ركبنــا يف الســيارة وكان ركاب الســيارة‬\n‫هــم ‪....‬و‪ ....‬وانــا و‪....‬وأنــا أشــك هــل يوجــد شــخص خامــس أو ال ألن‬\n‫الواقعــة قدميــة وال اعلــم هــل قــام أحــد بعدهــا يف الســيارة او ال بعــد ذلــك‬\n‫توجهنــا ملخطــط مقابــل محطــة ‪....‬وقابلنــا يف خيمــة منصوبــة يف املوقــع‬\n‫عمــد أحدهمــا اســمه ‪ ....‬و‪ ....‬أو ‪ ....‬وكان املوقــع مكتــض‬       ‫شــخصني ّ‬\n‫بالزبائــن بعــد ذلــك تفــاوض ‪ ....‬مــع أحــد العمــد وطــرح املخطــط علــى‬\n‫األرض واختــار ‪ ......‬قطعــا ال أعرفهــا ثــم ســلم لــه مبلغــا قــدره‪ :‬أربعــة‬\n‫وتســعون ألــف وخمســمائة ريــال ثــم اشــترى ‪....‬قطعــة واحــدة ورأيته يســلم‬\n‫ألحــد العمــد مبلغــا قــدره‪ :‬خمســة عشــر ألــف ريــال ثــم قــال أحــد العمــد‬\n‫إن هــذه األراضــي لهــا مســتقبل وهــي ألميــر وناجحــة وإذا مــا جنــح‬\n‫املخطــط فعلــى مســؤليتي)‪ ،‬هكــذا شــهد‪ .‬وبســؤاله عــن القطــع التــي‬\n‫اشــتراها ‪....‬أجــاب قائــا‪ :‬ال أعلــم عددهــا‪ ،‬هكــذا أجــاب‪ .‬وبعــرض‬\n‫الشــاهد وشــهادته علــى املدعــى عليــه وكالــة أجــاب قائــا‪ :‬أطلــب مهلــة‬\n‫لإلجابــة عنهــا‪ ،‬هكــذا أجــاب‪ .‬ثــم جــرى تزكيــة الشــهود مــن قبــل ‪....‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪....‬و‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الهويــة الوطنيــة رقــم ‪....‬فشــهد كل واحــد منهمــا قائــا اشــهد‬\n‫هلل بعدالــة وثقــة الشــاهدين املذكوريــن اعــاه هكــذا شــهدا وبســؤال‬\n‫املدعــي عــن زيــادة بينــه أجــاب قائــا اكتفــي مبــا قدمــت هكــذا اجــاب‪.‬‬\n‫ويف يــوم األحــد املوافــق‪1434/07/23 :‬ه ـ حضــر املدعــي أصالــة‬\n‫ووكالــة‪ .... :‬واملدعــى عليــه وكالــة‪ ،.... :‬املثبــت حضورهمــا يف جلســة‬\n\n\n                                                                                       ‫‪10‬‬\n\f     ‫ســابقة‪ ،‬ثــم قــرر املدعــى عليــه قائــا‪ :‬أن موكلــي لم يســتلما مــن املدعي‬\n     ‫أصالــة ووكالــة أي مبلــغ مالــي ‪ ،‬وصحيــح أن العقــارات محــل النــزاع‬\n     ‫عليهــا مشــكلة ولــم يتــم إفراغهــا‪ ،‬وموكلــي أيضــا ذهبــت أموالهمــا يف‬\n     ‫هــذه األراضــي‪ ،‬هكــذا قــرر‪ .‬وبســؤال املدعــى عليــه وكالــة عمــا‬\n     ‫اســتمهل مــن أجلــه أجــاب قائــا‪ :‬أطلــب مهلــة ثانيــة‪ ،‬هكــذا أجــاب‪ .‬ويف‬\n     ‫يــوم اإلثنــن املوافــق‪1434/07/24 :‬ه ـ حضــر املدعــي أصالــة ووكالــة‪:‬‬\n     ‫‪....‬واملدعــى عليــه وكالــة‪ ،.... :‬املثبــت حضورهمــا يف جلســة ســابقة‪ ،‬ثــم‬\n     ‫قــرر املدعــى عليــه وكالــة قائــا‪ :‬إن شــهادة الشــاهد االول ‪ ...‬ســقطت‬\n     ‫مــن شــهادته كلمــة‪ :‬وخمســمائة فتكــون بعــد التصحيــح (بعدهــا رأيــت‬\n     ‫‪....‬يســلم ألحــد املدعــى عليهــا إمــا ‪....‬وإمــا ‪....‬مبلغــا قــدره‪ :‬أربعــة وتســعون‬\n     ‫ألــف وخمســمائة ريــال منــه وبســؤال املدعــى عليــه وكالــة عمــا اســتمهل‬\n     ‫مــن أجلــه أجــاب قائــا‪ :‬إن املدعــي أصالــة ووكالــة قــد أحضــر شــاهدين‬\n     ‫غيــر الشــاهدين احلاضريــن يف صــك احلكــم املنقــوض‪ ،‬وممــا يــدل علــى‬\n     ‫أن الشــهود يف صــك احلكــم املنقــوض لــم يكونــوا حاضريــن مــع املدعي‬\n     ‫عنــد تســليم املبلــغ مــا جــاء يف شــهادة الشــاهد الثانــي‪.... :‬ونــص احلاجــة‬\n     ‫منهــا‪( :‬وكان ركاب الســيارة هــم ‪....‬و‪ ....‬وأنــا و‪ ....‬وأنــا اشــك هــل‬\n     ‫يوجــد شــخص خامــس أو ال)‪ ،‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى‬\n     ‫املدعــي أصالــة ووكالــة أجــاب قائــا‪ :‬الشــاهدان املذكــوران يف صــك‬\n     ‫احلكــم املنقــوض كانــا يف املوقــع‪ ،‬ولــم يكونــا معــي يف الســيارة‪،‬‬\n     ‫هكــذا أجــاب‪ .‬وبســؤال املدعــى عليــه وكالــة عــن زيــادة طعــن أجــاب‬\n     ‫قائــا‪ :‬الشــاهد األول (‪ )....‬ملــا ُســئل عــن عــدد القطــع التــي اشــتراها‬\n     ‫املدعــي أصالــة أجــاب بأنهــا (‪ )27‬قطعــة أرض وأن املدعــي أصالــة‬\n     ‫ووكيلــة يتفاوضــون علــى هــذا العــدد مــع موكلـ ّـي‪ ،‬وشــهد بــأن ‪...‬ـ‬\n\n\n‫‪11‬‬\n\f‫موكل املدعي أصالة ـ قام بتســليم قيمة قطعتني ألحد ‪ ،......‬والشــاهد‬\n‫الثانــي (‪ )....‬أجــاب بــأن ‪ ....‬تفــاوض مــع أحــد ‪ ......‬وبســؤاله عــن عــدد‬\n‫القطــع أجــاب ال أعلــم عددهــا وأن ‪...‬اشــترى قطعــة واحــدة‪ ،‬وبذلــك‬\n‫يتبـ ّـن تعــارض شــهادة الشــهود ويجعلهــا غيــر موصلــة‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبعــرض ذلــك علــى املدعــي أصالــة ووكالــة أجــاب قائــا‪ :‬الواقعــة محــل‬\n‫أن املبلــغ املدعــى بــه وصــل‬\n                             ‫النــزاع كانــت قبــل ســبع ســنوات‪ ،‬واملهــم ّ‬\n‫للمدعــى عليهمــا بغــض ال َّنظــر عــن عــدد القطــع‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبســؤال املدعــى عليــه وكالــة عــن زيــادة طعــن أجــاب قائــا‪ :‬تعارضــت‬\n‫دعــوى املدعــي أصالــة ووكالــة مــع شــهادة الشــهود عنــد بدايــة الدعــوى‬\n‫يف الصــك املنقــوض‪ ،‬فقــد أقــام املدعــي الدعــوى ضــد موكلـ ّـي مدعيـ ًا‬\n‫أنهمــا باعــا لــه ثالثــن قطعــة أرض علــى طريــق الســاحل‪ ،‬وقــدم املدعــي‬\n‫إثبات ـ ًا لدعــواه ســبعة وعشــرون ورقــة مبايعــة لســبعة وعشــرون قطعــة‪،‬‬\n‫هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي أصالــة ووكالــة أجــاب‬\n‫قائــا‪ :‬اإلثباتــات كانــت مفقــودة عنــدي وقــد وجدتهــا بعــد إقامــة‬\n‫الدعــوى الســابقة‪ ،‬هكــذا أجــاب وبســؤال املدعــى عليــه وكالــة عــن‬\n‫زيــادة طعــن أجــاب قائــا‪ :‬يف الصــك املنقــوض ذكــر املدعــي أصالــة‬\n‫ووكالــة أن لــه يف ذمــة موكلـ ّـي مبلــغ قــدره‪ :‬مائــة وثالثــة عشــر ألــف‬\n‫ريــال‪ ،‬ويف هــذه الدعــوى يقــرر أنــه لــه بذمــة موكلــي مبلغــا قــدره‪ :‬مائــة‬\n‫وتســعة آالف وخمســمائة ريــال‪ ،‬هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــي أصالــة ووكالــة أجــاب قائــا‪ :‬كنــت أدعــي أنهــا ثمان وعشــرين‬\n‫قطعــة تخصنــي وثنتــان ملوكلــي‪ ،‬واتضــح لــي أنهــا ســبع وعشــرين قطعــة‬\n‫تخصنــي وثنتــان ملوكلــي‪ ،‬هكــذا أجاب‪ .‬وبســؤال املدعــى عليه وكالة‬\n‫عــن زيــادة طعــن أجــاب قائــا‪ :‬أكتفــي مبــا قدمــت‪ ،‬هكــذا أجــاب‪.‬‬\n\n\n                                                                                     ‫‪12‬‬\n\f     ‫عنــد ذلــك سـلّم مذكــرة مكونــة مــن أربــع ورقــات جــرى اطالعنــا عليها‬\n     ‫وضمهــا ألوراق املعاملــة علمــا بــأن مضمونهــا مرصــود أعــاه‪ .‬وبســؤال‬\n     ‫املدعــى عليــه وكالــة عــن قيــام موكليــه بكتابــة العقــد أجــاب قائــا‪:‬‬\n     ‫إن موكلــي لــم يكتبــا العقــد بأيديهمــا‪ ،‬هكــذا أجــاب‪ .‬وبســؤاله عــن‬\n     ‫ســبب قيــام موكليــه بالشــاهد ومصلحتهمــا مــن ذلــك أجــاب قائــا‪:‬‬\n     ‫ليــس لهــم مصلحــة‪ ،‬ولكــن إحســانا للنــاس‪ ،‬هكــذا أجــاب‪ .‬وبســؤال‬\n     ‫املدعــى عليــه وكالــة عــن عالقــة موكليــه باملدعــي أصالــة ووكالــة‬\n     ‫أجــاب قائــا‪ :‬ليــس بينهمــا عالقــة إطالقــا وليــس بينهمــا صداقــة‪،‬‬\n     ‫هكــذا أجــاب‪ .‬وبســؤاله هــل شــهد موكليــه مــع أحــد غيــر املدعــي‬\n     ‫أصالــة وموكلــه أجــاب قائــا‪ :‬يشــهدون لــكل مــن يطلبهــم يف املوقــع‪،‬‬\n     ‫هكــذا أجــاب‪ .‬وبســؤال املدعــي أصالــة ووكالــة عــن العقــود أبــرز‬\n     ‫عقــودا عدهــا ‪ 29‬عقــدا للقطــع رقــم‪ 381( :‬ـ ‪ 382‬ـ ‪ 383‬ـ ‪ 384‬ـ ‪ 385‬ـ‬\n     ‫‪ 386‬ـ ‪ 387‬ـ ‪ 388‬ـ ‪ 389‬ـ ‪ 390‬ـ ‪ 391‬ـ ‪ 392‬ـ ‪ 393‬ـ ‪ 366‬ـ ‪ 367‬ـ ‪ 368‬ـ ‪369‬‬\n     ‫ـ ‪ 370‬ـ ‪ 371‬ـ ‪ 372‬ـ ‪ 373‬ـ ‪ 374‬ـ ‪ 375‬ـ ‪ 376‬ـ ‪ 377‬ـ ‪ 378‬ـ ‪ 379‬ـ ‪ 993‬ـ‬\n     ‫‪ )994‬وجــرى اطالعنــا عليهــا كاملــة ونــص احلاجــة منهــا‪( :‬عقــد بيــع‪،‬‬\n     ‫الطــرف األول‪ :‬صاحــب الســمو امللكــي ‪ ....‬حامــل حفيظــة رقــم‪.... :‬‬\n     ‫التاريــخ‪1417/12/18 :‬ه ـ عنوانــه الريــاض‪ ،‬لقــد بــاع لطــرف األول‬\n     ‫للطــرف الثانــي العقــار قطعــة رقــم‪ 381 :‬والواقــع يف شــارع طريــق ‪....‬‬\n     ‫واملســاحة اإلجماليــة ‪ 500‬م وذلــك بقيمــة إجماليــة مقدارهــا‪ :‬ســدد نقــدا‬\n     ‫كاملــة‪ .‬ثانيــا‪ :‬قبــل املشــتري العقــار املذكــور أعاله وبنفــس املواصفات‬\n     ‫املذكــورة ودفــع مــن أصــل القيمــة مبلغــا قــدره‪ :‬ســدد نقــدا‪( .‬ال يوجــد‬\n     ‫بنــد ثالثــا) رابعــا‪ :‬يعتبــر هــذا العقــد مبايعــة شــرعية حتــى يتــم تســجيله‬\n     ‫طــرف كاتــب عــدل حســب املتبــع وهــو ملــزم لــكال الطرفــن‪ .‬خامسـاً‪:‬‬\n\n\n‫‪13‬‬\n\f‫قــرأ العقــد كال الطرفــن ووافقــا علــى كل مــا جــاء بــه وهمــا بكامــل‬\n‫قواهمــا املعتبــرة شــرعا ووقعــا عليــه مبحــض إرادتهمــا واختيارهمــا‪.‬‬\n‫سادســا‪ :‬ســلم لــكل مــن الطرفــن نســخة مــن هــذا العقــد بواســطة‬\n‫الطــرف الثالــث‪ .‬ســابعا‪ :‬إذا لــم يقــم الطــرف الثانــي بدفــع باقــي القيمــة‬\n‫يف املوعــد فــإن للطــرف األول احلــق يف التصــرف يف املبــاع‪ .‬ثامنــا‪ :‬متــت‬\n‫املبايعــة بتاريــخ (بــدون أرقــام)‪ .‬تاســعا‪ :‬مت االتفــاق بينهمــا بالتراضــي ومت‬\n‫التوقيــع بينهمــا علــى مــا ذكــر أعــاه بشــهادة الشــهود‪ .‬الطــرف األول‬\n‫البائــع توقيــع الطــرف الثانــي املشــتري بــدون توقيــع شــاهد ‪....‬توقيــع ‪....‬‬\n‫توقيــع)‪ .‬ا‪ .‬ه ـ وجميــع العقــود البالــغ عددهــا تســعة وعشــرون عقدا بنفس‬\n‫الصيغــة املذكــورة أعــاه‪ ،‬عــدا عقــد القطعــة رقــم‪ 993 :‬والقطعــة رقــم‪:‬‬\n‫‪ 994‬فــإن اســم املشــتري فيهمــا هــو‪ ،.... :‬وباقــي العقــد هــو نــص مــا هــو‬\n‫مــدون أعــاه‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة أجــاب قائــا‪27 :‬‬\n‫عقــدا ال يشــير أنهــا للمدعــي أصالــة‪ ،‬وقــد كتــب موكلــي اســمائهما‬\n‫يف الشــهادة علــى العقــد ولــم يحــررا مضمــون العقــد‪ ،‬هكــذا أجــاب‪.‬‬\n‫وبعــرض ذلــك علــى املدعيــة أصالــة ووكالــة أجــاب قائــا‪ :‬إن املدعــى‬\n‫عليــه ‪....‬قــال لــي إذا أردت بيعهــا غــدا فــا تكتــب اســمك عليهــا‪ ،‬وقــد‬\n‫كان دور ‪ ....‬الــدالل ويتفــاوض مــع النــاس ويتفــق معهــم ثــم يأخذنــا‬\n‫لناحيــة أخــرى موجــود بهــا ‪....‬اســتالم املبالــغ ووضعهــا يف الشــنطة‬\n‫الســوداء‪ ،‬هكــذا أجــاب‪ .‬ونظــرا لوصــول القضيــة لهــذا احلــد فقــد‬\n‫القضيــة‪ .‬فبنــاء علــى مــا ســلف‪ ،‬وألن‬\n                                   ‫ّ‬       ‫قــررت قفــل بــاب املرافعــة والبــت يف‬\n‫املدعــى عليــه وكالــة أنكــر دعــوى املدعــي أصالــة ووكالــة‪ ،‬وأقــام‬\n‫املدعــي أصالــة ووكالــة ّبينــة تؤيــد دعــواه‪ ،‬وهــي‪ :‬شــهادة الشــاهد ‪....‬‬\n‫واملتضمنــة‪ :‬أن املدعــى عليهمــا أصالــة تفاوضــا مــع املدعــي أصالــة ‪....‬‬\n\n\n                                                                                      ‫‪14‬‬\n\f     ‫وموكلــه ‪....‬علــى عــدد ‪ 27‬قطعــة أرض يف املخطــط الذهبــي‪ ،‬وأن‬\n     ‫املدعــى عليــه أصالــة ‪ ....‬قــرر للمدعــي أصالــة وموكلــه أن األراضــي‬\n     ‫موثوقــة وليــس فيهــا مشــكلة وأنــه قــال‪( :‬أنــا قبيلكــم)‪ ،‬ثــم ســلم‬\n     ‫املدعــي أصالــة ‪....‬مبلغــا قــدره‪ :‬أربعــة وتســعون ألــف وخمســمائة ريــال‬\n     ‫ألحــد املدعــى عليهمــا‪ ،‬وســلم موكلــه ‪...‬مبلغــا قــدره‪ :‬خمســة عشــر‬\n     ‫ألــف ريــال ألحــد املدعــى عليهمــا ولــم يحــدده‪ .‬ا‪.‬ه ـ كمــا قــدم املدعــي‬\n     ‫أصالــة ووكالــة بينــة أخــرى تؤيــد دعــواه وهــي شــهادة الشــاهد ‪....‬‬\n     ‫واملتضمنــة‪ :‬أنــه كان بصحبــة املدعــي أصالــة ووكالــة يف املوقــع‬\n     ‫ووجــدوا املدعــى عليهمــا وتفــاوض ‪ ......‬مــع أحــد املدعــى عليهمــا علــى‬\n     ‫قطــع مــن املخطــط ثــم س ـلّم لــه مبلغــا قــدره‪ :‬أربــع وتســعون ألــف‬\n     ‫وخمســمائة ريــال‪ ،‬كمــا سـلّم موكلــه مبلغــا قــدره‪ :‬خمســة عشــر ألــف‬\n     ‫ريــال ألحــد املدعــى عليهمــا‪ ،‬وقــرر بعــد اســتالمه للمبلــغ قائــا‪ :‬إذا مــا‬\n     ‫جنــح املخطــط فعلــى مســؤوليتي‪ .‬ا‪ .‬ه ـ وهاتــان الشــهادتان تــدل علــى أن‬\n     ‫املدعــى عليهمــا تفاوضــا مــع املدعــي أصالــة وموكلــه‪ ،‬وقــد صــرح‬\n     ‫أحدهمــا بأنــه ضامــن ملــال املدعــن حــال وجــود مشــكلة علــى العقــارات‬\n     ‫محــل البيــع‪ ،‬وهــذا يــدل على أنهما متضامنني يف هذا العمل ومســؤوالن‬\n     ‫عنــه فاســتالم أحدهمــا كاســتالمهما معــا‪ ،‬وضمــان الــدرك املعــروف‬\n     ‫بضمــان العهــدة بــأن يضمــن ثمــن املبيــع إن ظهــر مســتحقا ممــا هــو مقــرر‬\n     ‫فقهــا‪ ،‬قــال يف الــروض املربــع ‪( :103/5‬ويصــح ضمــان عهــدة مبيــع بــأن‬\n     ‫يضمــن الثمــن إذا اســتحق املبيــع)‪ ،‬كمــا أنهمــا قــد باشــرا العقــد‬\n     ‫والتفــاوض وهــذا موجــب لضمانهمــا بإعــادة مــا اســتلماه‪ ،‬ينضــاف لذلك‬\n     ‫خلـ ّـو العقــد مــن كتابــة قيمــة املبيــع يف تســع وعشــرين عقدا يــدلّ تبييتهم‬\n     ‫للكــذب واملراوغــة‪ ،‬ويضــاف أيضــا أن شــهادة املدعــى عليهمــا لــكل‬\n\n\n‫‪15‬‬\n\f‫مــن طلــب منهمــا الشــهادة يف املوقــع أمــر يدعــو للتهمــة ويقــوي دعــوى‬\n‫ـرت املدعــى‬  ‫املدعــي أصالــة ووكالــة جتاههمــا‪ ،‬لذلــك كلــه فقــد أمـ ُ‬\n‫عليهمــا (‪ ....‬و‪ )....‬متضامنــن أن يس ـلّما للمدعــي أصالــة‪.... .... :‬مبلغــا‬\n‫قــدره‪ :‬أربعــة وتســعون ألــف وخمــس مئــة ريــال‪ ،‬ويسـلّما ملوكلــه‪.... .... :‬‬\n‫مبلغــا قــدره‪ :‬خمســة عشــر ألــف ريــال‪ ،‬وبذلــك قضيت‪ .‬وبإعــان احلكم‬\n‫قــرر املدعــي أصالــة ووكالــة قناعتــه باحلكــم‪ ،‬أمــا املدعــى عليــه‬\n‫اعتراضيــة‪ ،‬فجــرى‬\n                ‫ّ‬         ‫ـتعد بتقــدمي الئحــة‬\n                                           ‫وكالــة فقــرر عــدم القناعــة واسـ ّ‬\n‫تســليمه نســخة مــن احلكــم وأفهمتــه بــأن لــه احلــق يف تقــدمي اعتراضــه‬\n‫خــال ثالثــون يوم ـ ًا اعتبــار ًا مــن هــذا اليــوم‪ ،‬وإذا انتهــت املـ ّـدة احملــددة‬\n‫حقــه يف االعتــراض بطلــب االســتئناف‬          ‫ولــم يقــدم الئحتــه ســقط ّ‬\n‫القطعيــة‪ .‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                       ‫ّ‬         ‫واكتســب احلكــم‬\n                  ‫محمد وعلى آله وصحبه وسلم‪ .‬حرر يف‪1434/07/24 :‬هـ‬\n‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪.:‬فقــد‬\n‫جــرى اطالعنــا نحــن رئيــس وعضــوي الدائــرة احلقوقيــة الرابعــة يف‬\n‫محكمــة االســتئناف مبنطقــة مكــة املكرمــة علــى الصــك الصــادر‬\n‫مــن فضيلــة الشــيخ‪.... /‬القاضــي باحملكمــة العامــة بجــدة واملســجل‬\n‫بعــدد ‪34277805‬وتاريــخ ‪1434/7/24‬هـ ـ املتضمــن دعــوى ‪( ....‬أصالــة‬\n‫ووكالــة) ضــد ‪....‬و‪ ....‬واحملكــوم فيــه مبــا دون باطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى‬\n    ‫احلكــم‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                           ‫‪16‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":5,"source_page_end":16,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e4704a977cd0344a39f60ed3feaab23a040996724cf5e5a47e1f8ecdcc72293e","normalized_text_hash":"652a39fc85a84e625779814c306d7de27d357b9d249ead6f4a3d354310684d85","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p5-34277805"},{"id":"8bfde1b0-1b54-54c3-b523-2f41e1bd57a0","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -مزرعة -فسخ العقد لوجود غن يف ثمنها -تقدير الثمن للمبيع عن طريق قسم اخلبراء -الغن الفاحش يثبت به اخليار ومرده العرف -احلكم بفسخ البيع ورد ثمن املبيع -التماس إعادة النظر -رفض موضوع ا.","document_number":"34167086","case_number":"32500212","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"بيع -مزرعة -فسخ العقد لوجود غن يف ثمنها -تقدير الثمن للمبيع عن طريق قسم اخلبراء -الغن الفاحش يثبت به اخليار ومرده العرف -احلكم بفسخ البيع ورد ثمن املبيع -التماس إعادة النظر -رفض موضوع ا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫تاريخه‪1434/3/21:‬هـ‬\n                     ‫ُ‬                ‫َر ْق ُم َّ‬\n                        ‫الص ِّك‪34167086 :‬‬\n                       ‫َر ْق ُم الدعوى‪32500212 :‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34277706‬تاريخه‪1434/7/24 :‬هـ‬\n\n\n     ‫بيــع ‪ -‬مزرعــة ‪ -‬فســخ العقــد لوجــود غــن يف ثمنهــا ‪ -‬تقديــر الثمــن‬\n     ‫للمبيــع عــن طريــق قســم اخلبــراء ‪ -‬الغــن الفاحــش يثبــت بــه اخليــار‬\n     ‫ومــرده العــرف ‪ -‬احلكــم بفســخ البيــع ورد ثمــن املبيــع ‪ -‬التمــاس إعــادة‬\n                                                       ‫النظــر ‪ -‬رفــض موضوع ـ ًا‪.‬‬\n\n\n\n\n     ‫‪ -1‬قــول ابــن قدامــة‪« :‬وال حتديــد للغــن يف املنصــوص عــن أحمــد وقيــل‬\n     ‫بالثلــث وهــو قــول مالــك لقــول النبــي صلــى اهلل عليــه وســلم «والثلــث‬\n     ‫كثيــر» أخرجــه البخــاري ومســلم قيــل «بالســدس» وقيــل «مــا ًال يتغابــن‬\n     ‫النــاس بــه يف العــادة ألن مــا ال يــرد الشــرع بــه يرجــع فيــه إلــى العــرف»‬\n                                                                  ‫املغنــي (‪.)36،37/6‬‬\n     ‫‪ -2‬قــول شــيخ اإلســام ابــن تيميــة‪« :‬فــا يجــوز أن يبــاع املسترســل إال‬\n     ‫بالســعر الــذي يبــاع فيــه غيــره‪ ،‬وال يجــوز الحــد استرســل إليــه إن يغــن‬\n                        ‫يف الربــح غبنــا يخــرج عــن العــادة»‪ .‬الفتــاوى (‪.)360/29‬‬\n     ‫‪ -3‬قــول املــرداوي‪« :‬فتلخــص أن املسترســل هــو اجلاهــل بالقيمــة ســواء‬\n                                  ‫كان بايعـ ًا أو مشــتري ًا»‪ .‬اإلنصــاف (‪.)397/4‬‬\n     ‫‪ -4‬قــول البهوتــي‪« :‬واملــراد هنــا اجلاهــل بالقيمــة مــن بائــع و مشــتر‬\n     ‫وال يحســن مياكــس فلــه اخليــار إذا غــن املذكــور الــذي يخــرج عــن‬\n     ‫العــادة ألنــه حصــل جلهلــه باملبيــع فثبــت لــه اخليــار»‪ .‬كشــاف القنــاع‬\n                                                                           ‫(‪. )435/7‬‬\n‫‪17‬‬\n\f‫ادعــى املدعــي بأنــه اشــترى مــن املدعــى عليــه مزرعــة موصوفــة يف‬\n‫الدعــوى بالثمــن املذكــور وســلمه جــزء مــن الثمــن ثــم تبــن لــه أن املــزارع‬\n‫املجــاورة لهــا أقــل مــن ثمنهــا بكثيــر وأنــه مغبــون يف هــذه البيعــة‪ ،‬ولــذا‬\n‫طلــب تقديــر قيمــة املزرعــة وإعــادة املبلــغ الزائــد الــذي دفعــه للمدعــى‬\n‫عليــه أو فســخ البيــع ‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى ودفــع‬\n‫بــأن املدعــي عايــن املزرعــة مــا ال يقــل عــن خمــس مــرات ثــم أصــر علــى‬\n‫شــرائها كمــا أن غيــره طلــب شــراء املزرعــة فأخبــره بأنــه قــد باعهــا‬\n‫علــى املدعــي ولذلــك فهــو غيــر مســتعد بفســخ البيــع أو تعويــض املدعــي‪،‬‬\n‫قــررت احملكمــة تكليــف قســم اخلبــراء بتقديــر قيمــة املزرعــة وقــت‬\n‫بيعهــا فأفــادوا بــأن الثمــن الــذي بيعــت بــه املزرعــة فيــه غــن علــى‬\n‫املشــتري‪ ،‬املدعــي غــن يف البيعــة املذكــورة غبنـ ًا جتــاوز الثلــث أكثــر‬\n‫مــن ســت مــرات و بضعــف قيمتهــا ثــاث مــرات مبــا يعتبــر غبنـ ًا فاحشـ ًا‬\n‫ظاهــر ًا ‪ ،‬قضــت احملكمــة بثبــوت وجــود غــن فاحــش علــى املدعــي‬\n‫مــن البيعــة املذكــورة و حكمــت بفســخ البيــع املذكــور ومبوجبــه يلــزم‬\n‫املدعــي بإعــادة املزرعــة املذكــورة للمدعــى عليــه وإعــادة املدعــى عليــه‬\n‫املبلــغ الــذي اســتلمه للمدعــي‪ ،‬قنــع املدعــي باحلكــم وعــارض عليــه‬\n‫املدعــى عليــه ‪ ،‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪،‬‬\n‫تقــدم املدعــى عليــه بالتمــاس إعــادة نظــر إلــى محكمــة االســتئناف‬\n‫فقــررت باألكثريــة رفــض االلتمــاس لعــدم انطبــاق التعليمــات عليــه ‪.‬‬\n\n\n\n\n                                                                                       ‫‪18‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n     ‫باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n     ‫احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 32500212‬وتاريــخ‬\n     ‫‪1432/11/05‬ه ـ املقيــدة باحملكمــة برقــم ‪ 321388092‬وتاريــخ‬\n     ‫‪1432/11/5‬ه ـ ففــي يــوم الثالثــاء املوافق‪1432/11/20‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 09 : 15‬وفيهــا حضــر (‪ )....‬ســعودي اجلنســية مبوجــب‬\n     ‫الســجل املدنــي رقــم (‪ )....‬وأدعــى علــى احلاضــر معــه يف مجلــس‬\n     ‫احلكــم(‪ )....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )....‬بقولــه‪:‬‬\n     ‫إننــي اشــتريت مــن املدعــى عليــه مزرعــة واقعــة يف (‪ )....‬مملوكــة لــه‬\n     ‫مبوجــب صــك شــرعي وقــد دلنــي عليهــا املدعــو (‪ )....‬قبــل حوالــي ســنة‬\n     ‫ولكونــي مــن املنطقــة الشــرقية فقــد حضــرت(‪ )....‬و(‪ )....‬وقفــت عليهــا‬\n     ‫ثــم حضــرت يف املــرة الثانيــة واتفقــت مــع املدعــى عليــه علــى شــرائها‬\n     ‫مبليــون وخمســن ألــف ريــال وعملنــا العقــد ودفعــت لــه مائتــن وعشــرة‬\n     ‫أالف ريــال ثــم حضــرت للمــرة الثالثــة لإلفــراغ ودفعــت لــه ســبعمائة‬\n     ‫وخمســة وســتني ألــف ريــال وأفــرغ لــي األرض وبقــي لــه خمســة وســبعون‬\n     ‫ألــف ريــال ثــم تبــن لــي بعــد أن اشــتريتها أن املــزارع املجــاورة لهــا أقــل مــن‬\n     ‫ثمنهــا بكثيــر حيــث وجــدت علــى بعضهــا لوحــات للبيــع فســألت عنهــا‬\n     ‫فأفادونــي بأنهــا بثالثمائــة ألــف ريــال و أربعمائــة ألــف ريــال مــع أنهــا‬\n     ‫محيــاه وبهــا نخيــل قائــم أكثــر مــن املزرعــة التــي اشــتريتها فذكــرت‬\n     ‫ذلــك للمدعــى عليــه فقــال مــا عليــك منهــم إن مزرعتــك تســاوي أكثــر‬\n     ‫مــن ذلــك ولكــن تأكــدت بعــد ذلــك فتبــن بأننــي مغبــون يف هــذه البيعــة‬\n     ‫بحوالــي خمســمائة ألــف ريــال أو أكثــر ولــذا فأطلــب تقديــر املزرعــة‬\n‫‪19‬‬\n\f‫مــن هيئــة النظــر باحملكمــة أو مــن قبــل مكاتــب عقاريــة وإعــادة املبلــغ‬\n‫الزائــد الــذي دفعتــه للمدعــى عليــه أو فســخ البيــع علمـ ًا أننــي اشــتريتها‬\n‫بــدون كهربــاء وأنــا الــذي قمــت بإدخــال الكهربــاء لهــا هكــذا قــرر‬\n‫دعــواه وبعــرض ذلــك علــى املدعــى عليــه صــادق علــى أنــه بــاع املزرعــة‬\n‫املذكــورة علــى املدعــي باملبلــغ املذكــور إال أنــه قــال أن املدعــي حضــر‬\n‫مــن املنطقــة الشــرقية مــا ال يقــل عــن خمــس مــرات ويف كل مــرة يقــف‬\n‫علــى املزرعــة ويشــاهدها ويف كل مــرة أقــول لــه أذا أنــت غيــر جــازم‬\n‫علــى البيــع فــا مانــع لــدي مــن إنهــاء االتفــاق ولكنــه أصــر بعــد ذلــك‬\n‫علــى البيــع مــع أننــي ســبق أن عرضتهــا عليــه مبليــون وأربعمائــة ألــف‬\n‫ريــال ثــم نزلــت القيمــة إلــى مليــون وخمســن ثــم نزلــت القيمــة إلــى مليــون‬\n‫وخمســن ودفــع لــي املبالــغ متفرقــة إلــى أن مت اإلفــراغ وقــد بقــي لــي‬\n‫عنــده خمســة وســبعون ألــف ريــال لــم يدفعهــا إلــى األن وأطلــب إلزامــه‬\n‫بدفعهــا وليــس لــدي اســتعداد بفســخ البيــع أو تعويضــه علم ـ ًا أنــه يف‬\n‫إحــدى املــرات حضــر وقــد شــاهد زبون ـ ًا أخــر لشــرائها وطلــب منــي‬\n‫الزبــون األخــر بيعهــا فأفهمتــه بأننــي قــد بعتهــا علــى املدعــي هكــذا‬\n‫أجــاب وبعرضــه علــى املدعــي صــادق علــى انــه حضــر وشــاهد املزرعــة‬\n‫عــدة مــرات إال أنــه قــال إننــي أنــا مــن املنطقــة الشــرقية وال أعــرف أقيــام‬\n‫املــزارع ولكننــي مغبــون يف هــذه البيعــة غبن ـ ًا كبيــر ًا هكــذا أجــاب‬\n‫فجــرى محاولــة اإلصــاح بينهمــا فلــم نتمكــن مــن ذلــك وحيــث احلــال مــا‬\n‫ذكــر فقــد قــررت الكتابــة لقســم اخلبــراء للوقــوف علــى املزرعــة‬\n‫واإلفــادة عــن ذلــك وعليــه حصــل التوقيــع ‪ .‬ويف يــوم الثالثــاء املوافــق‬\n‫‪1433/2/23‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي أصالــه كمــا‬\n‫حضــر وكيــل املدعــى عليــه (‪)....‬ســعودي اجلنســية مبوجــب الســجل‬\n\n\n                                                                                        ‫‪20‬‬\n\f     ‫املدنــي رقــم (‪ )....‬الوكيــل الشــرعي عــن (‪ )....‬مبوجــب الوكالــة اخلاصــة‬\n     ‫الصــادرة مــن كاتــب عــدل املدينــة الثانيــة برقــم ‪ 51631‬وتاريــخ‬\n     ‫‪1431/8/21‬ه ـ جلــد ‪ 6497‬هــذا وقــد عــادة املعاملــة مــن قســم اخلبــراء‬\n     ‫الــذي جــاء فيــه مــا نصــه ‪ :‬نفيدكــم أنــه بالوقــوف على املزرعــة و بتطبيق‬\n     ‫الصــك رقــم ‪ 6/32‬وجــد مطابق ـ ًا واملزرعــة حتتــوي علــى بئــر ارتوازيــة‬\n     ‫وحوالــي أربعــن فســيلة مــن النخيــل بعضهــا ميــت وحوالــي عشــرة‬\n     ‫أحــواض برســيم ميتــه وبهــا نزلتــن كل نزلــة غرفتــن وحمــام ومطبــخ‬\n     ‫مســقوفه مــن الهنقــر احلديــد وبعــض اجلــدران الغيــر مســقوفه وحضائــر‬\n     ‫أغنــام ويوجــد باملزرعــة التيــار الكهربائــي وبالتجول واملشــاهدة وســؤال‬\n     ‫أربــاب اخلبــرة يف تلــك املنطقــة تقــدر قيمــة املزرعــة يف الوقــت احلالــي‬\n     ‫مببلــغ وقــدره أربعمائــة الــف ريــال وعلــى ذلــك فــإن بشــراء املزرعــة مببلــغ‬\n     ‫مليــون وخمســون ألــف ريــال غــن علــى املشــتري هــذا مــا ظهــر لنــا مســاح‬\n     ‫احملكمــة (‪ .)....( ، )....‬أه ـ ‪ .‬وحيــث إن قــرار اخلبــراء قدرهــا بالوقــت‬\n     ‫احلالــي بأربعمائــة ألــف ريــال يف حــن أن خطابنــا املوجــه لهــم هو تقديرها‬\n     ‫وقــت البيــع يف ذي القعــدة ‪1431‬ه ـ ولــذا فقــد قــررت إعــادة املعاملــة‬\n     ‫لقســم اخلبــراء لتقديرهــا وقــت البيــع‪ .‬ثــم طلــب الطرفــان مهلــة إلــى الغــد‬\n     ‫للجلــوس واإلفــادة وعليــه حصــل التوقيــع‪ .‬ويف يــوم االثنــن املوافــق‬\n     ‫‪1433/05/03‬هـ افتتحت اجللســة الســاعة ‪ 10 : 19‬وفيها حضر املدعي‬\n     ‫ولــم يحضــر املدعــى عليــه وال وكيــل عنــه مــع تبلغــه مبوعــد اجللســة لــذا‬\n     ‫جــرى إثباتــه‪ .‬ويف يــوم األحــد املوافــق ‪1434/01/04‬ه ـ افتتحــت اجللســة‬\n     ‫وفيهــا حضــر املدعــي أصالــة كمــا حضــر املدعــو(‪ )....‬ســعودي اجلنســية‬\n     ‫مبوجــب الســجل رقــم (‪ )....‬الوكيــل الشــرعي عــن (‪ )....‬مبوجــب‬\n     ‫الوكالــة الصــادرة مــن املدينــة برقــم ‪ 33453306‬يف ‪1433/12/20‬ه ـ‬\n\n\n‫‪21‬‬\n\f‫واملخــول فيهــا باملرافعــة واملدافعــة واالقــرار واالنــكار وطلــب اليمــن‬\n‫ورده واحضــار الشــهود واالســتالم والتســليم ‪...‬الــخ وقــد جــرى أعــادة‬\n‫عــرض الدعــوى علــى املدعــى عليــه وكالــة اجلديــد وقــال أن موكلــي‬\n‫يطلــب صــرف النظــر عــن دعــوى املدعــي حيــث ان بينهمــا عقــد مت‬\n‫التوقيــع عليــه بالتراضــي كمــا ان موكلــي ينفــي حصــول الغــن علــى‬\n‫املدعــي وبنــاء علــى ذلــك يطالبــه موكلــي باملتبقــي مــن املبلــغ وقــدره‬\n‫خمســة وســبعون الــف ريــال هكــذا أجــاب وبعرضــه علــى املدعــي قــال‪:‬‬\n‫إننــي أنــا (‪ )....‬مــن أهــل املنطقــة الشــرقية وكان لــي وكيــل يدعــى(‪)....‬‬\n‫و (‪ )....‬هــو الــذي اوقفنــي علــى مزرعــة (‪ )....‬و(‪ )....‬صاحــب مكتــب‬\n‫عقــاري وهــو الــذي دلنــي عليهــا ولكننــي أنــا الــذي وقعــت عقــد املبايعــة‬\n‫وأنــا الــذي قبلــت اإلفــراغ لــدي كاتــب العــدل وكنــت أتوقــع أن هــذه‬\n‫هــي القيمــة احلقيقيــة للمزرعــة ولكــن تبــن أن بهــا فــارق كبيــر ولــو‬\n‫كانــت الزيــادة خمســن ألــف أو ســبعني ألــف لقبلــت بهــا ولكنهــا‬\n‫اكثــر مــن ذلــك بكثيــر وأنــا الــذي قمــت بإدخــال الكهربــاء لهــا حيــث‬\n‫اشــتريتها بــدون كهربــاء كمــا أن قســم اخلبــراء وقفــوا عليهــا وقدروهــا‬\n‫بأربعمائــة ألــف ريــال وال زلــت علــى دعــواي ســابق ًا هكــذا أجــاب هــذا‬\n‫وقــد ســبق أن أعدنــا املعاملــة لقســم اخلبــراء لتقديــر قيمــة املزرعــة وقــت‬\n‫البيــع يف ذو القعــدة لعــام ‪1431‬ه ـ وليــس يف الوقــت احلاضــر فعــادت‬\n‫املعاملــة مــن قســم اخلبــراء مــرة اخــرى بشــرحهم رقــم ‪ 32/1388092‬يف‬\n‫‪1433/3/28‬ه ـ والــذي جــاء فيــه أنــه بســؤال أربــاب اخلبــرة يف املنطقــة‬\n‫عــن قيمــة العقــار أعــاه عــام ‪1431‬ه ـ أفادوا بــأن قيمتها يف ذلــك التاريخ‬\n‫حوالــي ثالثمائــة وخمســون ألــف ريــال ‪ ،‬القائــم بعمــل رئيــس اخلبــراء‬\n‫(‪ )....‬اهــ‪ .‬وبســؤال املدعــى عليــه وكالــه عمــا ذكــره املدعــي بأنــه‬\n\n\n                                                                                     ‫‪22‬‬\n\f     ‫أشــتري املزرعــة بــدون كهربــاء فقــال‪ :‬أنــا ال أدري وأطلــب إمهالــي‬\n     ‫لســؤال موكلــي ثــم قــال أطلــب متكينــي مــن االتصــال بــه حالي ـاً؟ فتــم‬\n     ‫متكينــه مــن االتصــال بــه وبعــد االتصــال قــرر بــأن موكلــه بــاع املزرعــة‬\n     ‫علــى املدعــي وبهــا كهربــاء هكــذا قــرر وبعرضــه علــى املدعــي قــال‪:‬‬\n     ‫إنــه لــم يكــن باملزرعــة عــدادات وطبلــون خــاص بهــا وإمنــا كان بهــا‬\n     ‫ســلك ممــدود مــن اجلــار فقــط وأنــا الــذي تقدمــت لشــركة الكهربــاء‬\n     ‫وأدخلــت للمزرعــة العــدادات والطبلــون اخلــاص بهــا وهــو مســجل باســمي‬\n     ‫أنــا شــخصي ًا هكــذا قــرر ‪ .‬وبعرضــه علــى املدعــى عليــه وكالــة قــال‪ :‬إن‬\n     ‫موكلــي ذكــر لــي أنــه ســبق أن تقــدم لشــركة الكهربــاء ومت توصيــل‬\n     ‫الكيبــل إلــى املزرعــة وأثنــاء ذلــك متــت املبايعــة فتــم تركيــب العــداد‬\n     ‫والطبلــون باســم املدعــي وموكلــي هــو الــذي دفــع رســوم التوصيــل‬\n     ‫والعــداد والطبلــون هكــذا قــرر وبعرضــه علــى املدعــي قــال‪ :‬غيــر‬\n     ‫صحيــح فأنــا الــذي راجعــت شــركة الكهربــاء وأنــا الــذي تقدمــت‬\n     ‫بالطلــب وأنــا الــذي دفعــت رســوم دخوليــة الكهربــاء مبلغـ ًا وقــدره ســبعة‬\n     ‫األف وعليهــا زيــادة كســور ال أذكرهــا وأدخلــت عــداد مبائــة أمبيــر‬\n     ‫وعــداد ًا أخــر بســتني أمبيــر أو خمســن وجميعهــا باســمي هكــذا أجــاب‬\n     ‫‪ .‬وبعرضــه علــى املدعــي قــال غيــر صحيــح وحيــث احلــال مــا ذكــر فقــد‬\n     ‫قــررت الكتابــة لشــركة الكهربــاء لإلفــادة عــن ذلــك ثــم طلــب املدعــى‬\n     ‫عليــه وكالــة االتصــال علــى موكلــه فأتصــل بــه أثنــاء اجللســة وقــرر‬\n     ‫موكلــه بــأن املدعــي هــو الــذي دفــع رســوم دخوليــة الكهربــاء واخلالصة‬\n     ‫أن املزرعــة ســبق تقــدمي الكهربــاء لهــا مــن قبــل موكلــي وباعهــا قبــل‬\n     ‫دخــول الكهربــاء واملدعــي هــو الــذي واصــل إدخــال الكهربــاء ثــم قــال‬\n     ‫‪ :‬أطلــب إمهالــي إلــى اجللســة القادمــة ملناقشــة ذلــك تفصيليـ ًا مــع موكلي‬\n\n\n‫‪23‬‬\n\f‫ولكننــي أؤكــد علــى أن البيــع صحيــح وال يوجــد غــن وأطلــب صــرف‬\n‫النظــر عــن دعــوى املدعــي ورفعــت اجللســة وبــاهلل التوفيــق ‪ .‬ويف يــوم‬\n‫األربعــاء املوافــق ‪1434/2/6‬ه ـ افتتحــت اجللســة وفيهــا حضــر الطرفــان‬\n‫وصــادق املدعــى عليــه وكالــة بــأن املدعــي هــو الــذي دفــع رســوم‬\n‫الكهربــاء ومت إدخــال الكهربــاء بعــد دفــع الرســوم هكــذا قــرر ‪ ،‬هــذا‬\n‫وقــد قــدم املدعــى عليــه وكالــة مذكــره مطولــه ومت إرفاقهــا باملعاملــة‬\n‫وقــرر بــأن خالصتهــا بــان البيــع صحيــح وال يوجــد غــن علــى املدعــي‬\n‫حســب وضــع وصــرف موكلــي عليهــا وأســتالم املدعــي لهــا ونطلــب‬\n‫صــرف النظــر عــن دعــواه ودفــع املتبقــي عليــه هكــذا قــرر وبعرضــه على‬\n‫املدعــي قــرر بانــه ليــس لديــه جديــد وأن قســم اخلبــراء ســبق وأن وقفــوا‬\n‫علــى املوقــع مرتــن وقــرروا قراريــن بخصــوص الغــن املذكــور وقــرر‬\n‫كل منهمــا بأنــه ليــس لديــه خــاف مــا قدمــه ورفعــت اجللســة للتأمــل‬\n‫وإصــدار احلكــم الــازم وعليــه حصــل التوقيــع ‪ .‬وبعــد ويف يــوم الســبت‬\n‫املوافــق ‪1434/3/21‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي أصالــه‬\n‫كمــا حضــر املدعــي عليــه وكاله املدعو(‪ )....‬ســعودي اجلنســية مبوجب‬\n‫الهويــة الوطنيــة رقــم (‪ )....‬مبوجــب الوكالــة املذكــورة ســابق ًا وقــد‬\n‫جــرى االطــاع علــى صــك املزرعــة الصــادر مــن كتابــة العــدل االولــى‬\n‫برقم ‪ 940104006144‬يف ‪1432/1/6‬هـ املتضمن أن القطعة الزراعية‬\n‫رقــم (‪ )11‬مــن املخطــط رقــم (‪ )....‬الواقــع يف حــي (‪ )....‬باملدينــة حدودهــا‬\n‫وأطوالهــا شــما ًال القطعــة رقــم ‪ 7‬بطــول مأتــي متــر وجنوبـ ًا القطعــة رقــم‬\n‫(‪ )15‬بطــول مائتــي متــر وشــرق ًا شــارع بعــرض عشــرين متــر ًا ثــم القطعــة‬\n‫رقــم عشــرة بطــول مائــة وخمســن متــر ًا وغرب ـ ًا القطعــة رقــم أثنــا عشــر‬\n‫بطــول مائــة وخمســن متــر ًا ومســاحتها ثالثــون ألــف متــر مربــع واملســتند‬\n\n\n                                                                                     ‫‪24‬‬\n\f     ‫يف إفراغهــا علــى الصــك الصــادر مــن تلــك اإلدارة برقــم ‪ 8/32‬وجلــد‬\n     ‫‪ 1010‬يف ‪1419/8/10‬ه ـ قــد انتقلــت ملكيتهــا إلــى (‪ )....‬بثمــن قــدره‬\n     ‫مليــون ريــال ‪...‬الــخ‪ .‬كمــا جــرى االطــاع علــى الصــك املبنــي عليــه رقــم‬\n     ‫‪ 8/32‬وجــد يتضمــن أنــه صــادر مــن كتابــة العــدل االولــى باملدينــة‬\n     ‫بحضــور منــدوب وزارة الزراعــة وامليــاه بإفــراغ القطعــة وحــدوده‬\n     ‫للمدعــو(‪ )....‬الوكيــل الشــرعي عــن (‪ )....‬واملشــروح عليــه بانتقالهــا مــن‬\n     ‫ملــك (‪ )....‬إلــى ملــك (‪ )....‬بثمــن قــدره ســبعون ألــف ريــال واملشــروح عليــه‬\n     ‫بانتقالهــا مــن ملــك (‪ )....‬إلــى ملــك (‪ )....‬بثمــن قــدره مائــة وخمســون ألــف‬\n     ‫ريــال واملشــروح عليــه بانتقالهــا إلــى ملــك (‪ )....‬بثمــن قــدره مائتــي ألــف‬\n     ‫ريــال يف ‪1424/9/24‬ه ـ واملرفــق يف املعاملــة هــذا وقــد جــرى ســؤال‬\n     ‫املدعــي عــن حتديــد دعــواه فقــال‪ :‬إنــه يطلــب فســخ البيــع وإعــادة املزرعــة‬\n     ‫للمدعــى عليــه واســترداد املبلــغ الــذي دفعــه وقــدره تســعمائة وخمســة‬\n     ‫وســبعون ألــف ريــال هكــذا قــرر ومبحاولــة اإلصــاح بــن الطرفــن‬\n     ‫رفــض املدعــى عليــه فســخ البيــع ولــم نتوصــل إلــى صلــح بــن الطرفــن‬\n     ‫ـاء علــى مــا تقــدم مــن الدعــوى‬\n                                      ‫حيــث أصــر كل منهمــا علــى موقفــه‪ .‬فبنـ ً‬\n     ‫واإلجابــة وبعــد االطــاع علــى صــك املزرعــة املذكــورة والصــك املبنــي‬\n     ‫ـاء علــى مــا جــاء بقــراري قســم‬ ‫عليهــا واملبايعــات املشــروحة عليــه و بنـ ً‬\n     ‫اخلبــراء وحيــث صــادق املدعــى عليــه علــى أن املدعــي هــو الــذي أدخــل‬\n     ‫الكهربــاء للمزرعــة املذكــورة ودفــع رســومها وحيــث قــرر املدعــي أنــه‬\n     ‫يطلــب فســخ البيــع واســتردادا املبلــغ الــذي دفعــة وأنــه مغبــون يف ذلــك‬\n     ‫وحيــث صــادق املدعــى عليــه علــى بيعــه املزرعــة املذكــورة مبليــون‬\n     ‫وخمســن ألــف ريــال كمــا صــادق علــى اســتالمه تســعمائة وخمســة‬\n     ‫وســبعني ألــف ريــال وحيــث قــرر الفقهــاء أنــه ال حتديــد للغــن قــال أبــن‬\n\n\n‫‪25‬‬\n\f‫قدامــه‪( :‬وال حتديــد للغــن يف املنصــوص عــن أحمــد و قيــل‪ :‬بالثلــث وهــو‬\n‫قــول مالــك ألن النبــي صلــى اهلل عليــه وســلم ‪ ( :‬والثلــث كثيــر ) أخرجــه‬\n‫البخــاري ومســلم ‪ ،‬وقيــل‪ :‬بالســدس وقيــل‪ :‬مــاال يتغابــن النــاس بــه يف‬\n‫العــادة ألن مــاال يــرد الشــرع بــه يرجــع فيــه إلــى العــرف)‪ ،‬و قــال أبــن‬\n‫قدامــه (املسترســل‪ :‬هــو اجلاهــل بالقيمــة وال يحســن املبايعــة) املغنــي ج ‪6‬‬\n‫ص ‪ 37 ،36‬و قــال املــرداوي‪( :‬فتلخــص أن املسترســل هــو اجلاهــل‬\n‫بالقيمــة ســواء كان بايع ـ ًا أو مشــترياً) أ‪ .‬ه ـ اإلنصــاف نشــر دار أحيــاء‬\n‫التــراث العربــي ج ‪ 4‬ص ‪ ، 397‬و قــال البهوتــي ‪( :‬واملــراد هنــا اجلاهــل‬\n‫بالقيمــة مــن بائــع ومشــتر وال يحســن مياكــس فلــه اخليــار إذا غــن الغــن‬\n‫املذكــور الــذي يخــرج عــن العــادة ألنــه حصــل جلهلــه باملبيــع فثبــت لــه‬\n‫اخليــار) أ‪،‬ه ـ كشــاف القنــاع طبعــة وزارة العــدل ج ‪ 7‬ص ‪ ، 435‬و قــال‬\n‫شــيخ اإلســام أبــن تيميــة ‪( :‬فــا يجــوز أن يبــاع املسترســل إال بالســعر‬\n‫الــذي يبــاع فيــه غيــره وال يجــوز ألحــد أسترســل إليــه أن يغــن يف الربــح‬\n‫غبنـ ًا يخــرج عــن العــادة) أ‪.‬ه ـ الفتــاوى ج ‪ 29‬ص ‪ ، 360‬و حيــث أن تقديــر‬\n‫قســم اخلبــراء األخيــر بتقديــر قيمــة املزرعــة وقــت البيــع هــو ثالثمائــة‬\n‫وخمســون ألــف ريــال وال ســيما وهــي بــدون كهربــاء وبذلــك يتبــن بــأن‬\n‫املدعــي غــن يف البيعــة املذكــورة غبن ـ ًا جتــاوز الثلــث أكثــر مــن ســت‬\n‫مــرات وبضعــف قيمتهــا ثــاث مــرات مبــا يعتبــر غبن ـ ًا فاحش ـ ًا ظاهــر‬\n‫وحيــث لــم نتوصــل إلــى صلــح بــن الطرفــن فقــد أصــدرت االتــي‪ :‬ثبــت‬\n‫لــدي وجــود غــن فاحــش علــى املدعــي مــن البيعــة املذكــورة وحكمــت‬\n‫بفســخ البيــع املذكــور ومبوجبــه يلــزم املدعــي إعــادة املزرعــة املذكــورة‬\n‫للمدعــى عليــه وإعــادة املدعــى عليــه(‪ )....‬املبلــغ الــذي أســتلمه وقــدره‬\n‫تســعمائة وخمســة وســبعون ألــف ريــال للمدعــي(‪ )....‬هــذا مــا حكمــت‬\n\n\n                                                                                    ‫‪26‬‬\n\f     ‫بــه فليعلــم وبعرضــه علــى الطرفــن قــرر املدعــي القناعــة وأمــا املدعــى‬\n     ‫عليــه وكالــه فقــرر عــدم القناعــة وقــررت تســليم املدعــى عليــه وكالــه‬\n     ‫صــوره مــن صــك احلكــم لتقــدمي الالئحــة االعتراضيــة حســب املتبــع‬\n     ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى ســيدنا محمــد وعلــى آلــه وصحبه‬\n                                              ‫وسلم حرر بتاريخ ‪1434/3/21‬هـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم االحــد املوافــق ‪ 1434/08/07‬ه ـ فقــد‬\n     ‫عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة باخلطــاب‬\n     ‫رقــم‪ 331760913‬يف ‪1434/7/29‬ه ـ وبرفقهــا الصــك الصــادر منــا‬\n     ‫برقــم ‪ 34167086‬يف ‪1434/03/21‬ه ـ ومظهــر عليــه بالقــرار رقــم‬\n     ‫‪ 34277706‬يف ‪1434/07/24‬ه ـ الصــادر مــن الدائرة احلقوقية الســابعة‬\n     ‫املتضمــن املوافقــة علــى احلكــم واهلل املوفــق‪ .‬قاضــي اســتئناف (‪)....‬‬\n     ‫ختمــه وتوقيعــه ‪ ،‬قاضــي اســتئناف (‪ )....‬ختمــه وتوقيعــه ‪،‬رئيــس الدائــرة‬\n     ‫(‪ )....‬ختمــه وتوقيعــه ‪ .‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n                                                                  ‫وصحبــه وســلم ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد بنــاء علــى خطــاب محكمــة االســتئناف مبكــة‬\n     ‫املكرمــة رقــم ‪ 341887121‬يف ‪1434/8/17‬ه ـ بشــأن االلتماس املقدم‬\n     ‫مــن (‪ )....‬واملتضمــن طلــب إعــادة النظــر يف احلكــم الصــادر مــن الشــيخ‬\n     ‫(‪ )....‬واملرفــق معــه صــورة مــن قــرار الدائــرة الثالثــة لألحــوال الشــخصية‬\n     ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف‬\n     ‫مبكةاملكرمة ذات الرقم ‪ 34294745‬يف ‪1434/08/13‬هـ واملتضمن‬\n     ‫أنــه بدراســة املعاملــة تقــرر باألكثريــة رفــض االلتمــاس لعــدم انطبــاق‬\n     ‫التعليمــات عليــه وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                             ‫وســلم ‪.‬‬\n\n\n‫‪27‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"007a438a-91d3-5bc4-8c38-8ea7f2ceba0c","source_page_start":17,"source_page_end":27,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"862864e68a9f9a72ca20b6e077bda6540e2adf72f0264634c6cf00453548f97f","normalized_text_hash":"5a5507b05b02f14b1ea0a24e613a2dba59f06ef13038cd6e51c8aae1acf5ac6a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v2-p17-34167086"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

