SELECT 'moj-all-verified-judgments-review-002-chunk-083' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ebb754bd-aa65-5c72-b33d-e8b672ee26fc","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج واالجتار وتستر على مصدرها -إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -سوابق على املتهم قضى فيها باإلدانة -عقوبة","document_number":"33314559","case_number":"33285095","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/06/4","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد التعاطي والترويج واالجتار وتستر على مصدرها -إثبات بالشهادة -إدانة باحليازة املجردة عن القصد -سوابق على املتهم قضى فيها باإلدانة -عقوبة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33314559:‬تاريخه‪1433/06/4 :‬هـ‬\n                           ‫رقم الدعوى‪33285095:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 341584161‬تاريخه‪1434/11/12:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظورة بقصــد التعاطي والترويج‬\n       ‫واالجتــار وتســتر علــى مصدرهــا ‪ -‬إثبــات بالشــهادة ‪ -‬إدانــة باحليــازة‬\n       ‫املجــردة عــن القصــد ‪ -‬ســوابق علــى املتهــم قضــى فيها باإلدانــة ‪ -‬عقوبة‬\n                                                                  ‫بحدهــا األعلــى‪.‬‬\n\n\n\n              ‫املواد (‪ )39‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n       ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n       ‫بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة بقصــد الترويــج واالجتــار‬\n       ‫والتعاطــي وتســتره علــى مصدرهــا‪ ،‬واحلكــم عليــه بعقوبــة الســجن‬\n       ‫واجللــد والغرامــة واملنــع مــن الســفر طبقــا لنظــام مكافحــة املخــدرات‬\n       ‫واملؤثــرات العقليــة وبعقوبــة تعزيريــة علــى تســتر‪ ،‬مت تفتيــش منــزل‬\n       ‫املدعــى عليــه فعثــر فيــه علــى احلشــيش املخــدر واحلبوب احملظــورة‪ ،‬أثبت‬\n       ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة للحشــيش املخدر‬\n       ‫واإلمفيتامــن وااللبــرازوالم والكلونازيبــام‪ ،‬أنكــر أمــام احملكمــة مــا‬\n       ‫أســنده إليــه املدعــي العــام‪ ،‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي‬\n       ‫بيناتــه وقــررت ســماع شــهادة شــهود محضــر القبــض فشــهدوا بــأن‬\n\n‫‪295‬‬\n\f‫املضبوطــات كانــت يف اخلزنــة التــي أقــر املدعــى عليــه بأنهــا تخصــه وال‬\n‫يفتحهــا غيــره‪ ،‬قضــت احملكمــة بإدانــة املدعــى عليــه بحيــازة احلشــيش‬\n‫املخــدر واحلبــوب احملظــورة حيــازة مجــردة عــن قصــد االجتــار أو الترويــج‬\n‫أو التعاطــي وتوجــه الشــبهة لالجتــار والترويــج وصرفــت النظــر عــن‬\n‫مطالبــة املدعــي العــام تطبيــق العقوبــات الــواردة يف املــادة (‪ )38‬بحقــه‬\n‫وقــررت ســجنه ملــدة خمــس ســنوات وجلــده خمســمائة جلــدة مفرقــة علــى‬\n‫عشــر فتــرات لقــاء مــا أديــن بــه ولقــاء ســوابقه وتســتره كمــا قــررت‬\n‫تغرميــه مبلــغ ثالثــة آالف ريــال ومنعــه مــن الســفر خــارج اململكــة ملــدة‬\n‫خمــس ســنوات‪ ،‬عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪،‬‬\n‫قــررت محكمــة االســتئناف املصادقــة علــى احلكــم بعــد اإلجــراء‬\n                                                                       ‫األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزئيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالريــاض برقــم ‪ 33285095‬وتاريــخ ‪1433/04/24‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 33771195‬وتاريــخ ‪1433/04/24‬ه ـ ففــي يــوم‬\n‫السبت املوافق‪ 1433/05/08‬هـ افتتحت اجللسة الساعة ‪ 12 :05‬وفيها‬\n‫حضــر املدعــي العــام وادعــى علــى‪ ،........‬البالــغ مــن العمــر (‪ )33‬عامـ ًا ‪،‬‬\n‫‪ ................‬ســعودي اجلنســية مبوجب الســجل املدني رقم (‪ ،)........‬أعزب‬\n‫‪ ،‬متعلــم ‪ ،‬عاطــل ‪ ،‬يقيــم مبدينــة الريــاض‪ ،‬أوقــف بتاريخ ‪1433/1/2‬هـ‬\n‫وأودع شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة ومتديــد التوقيــف رقــم (ه ـ‬\n‫ر‪ )4430/5/1‬وتاريــخ ‪1433/1/10‬ه ـ علــى ذمــة قضيــة أخــرى‪ .‬حيــث‬\n\n                                                                                     ‫‪296‬‬\n\f      ‫أنــه بتاريــخ ‪1432/4/22‬ه ـ قبــض علــى كل مــن ‪1 /‬ـ ‪2‬ـ ـ ‪3‬ـ ـ (صــدر‬\n      ‫بحقهــم الئحــة دعــوى عامــه رقــم (ه ـ ر‪ )1389/5/1‬لعــام ‪1432‬ه ـ مــن‬\n      ‫قبــل إحــدى فــرق شــعبه املكافحــة والبحــث والتحــري التابعــة لــإدارة‬\n      ‫العامــة ملكافحــة املخــدرات مبنطقــة الريــاض حيــث وردت معلومــات‬\n      ‫للفرقــة بتاريــخ ‪1432/4/21‬ه ـ مــن أحــد املصــادر الســرية عــن قيــام‬\n      ‫(‪ )....‬بترويــج حبــوب الــروش احملظــورة واشــترط املصــدر عــدم إلقــاء‬\n      ‫القبــض علــى املــروج يف حينــه خوفــا مــن املــروج أو أعوانــه فتمــت املوافقــة‬\n      ‫علــى ذلــك عليــه مت االيعــاز للمصــدر باالتصــال علــى جــوال املــروج رقــم‬\n      ‫(‪ )........‬وهــو الرقــم الــذي متــت عليــه املفاوضــة وكان ذلــك علــى مســمع‬\n      ‫مــن رقيــب الفرقــة واســتعد املــروج ببيــع مــا عــدده (‪)5‬خمــس حبــات مــن‬\n      ‫حبــوب الــروش احملظــورة مببلــغ وقــدره (‪ )100‬مائــه ريــال ومت االتفــاق‬\n      ‫علــى مــكان التســليم واالســتالم أمــام منــزل املــروج علــى ضــوء ذلــك مت‬\n      ‫تفتيــش املصــدر تفتيشـ ًا دقيقـ ًا ومت تزويــده باملبلــغ املرقــم وقــدره (‪)100‬‬\n      ‫مائــه ريــال ومت تكليــف أحــد أفــراد الفرقــة مبرافقــة املصــدر ليكــون‬\n      ‫شــاهدا علــى إمتــام عمليــة الترويــج ومت تأمــن ســيارة مناســبه لهمــا عليــه‬\n      ‫مت االنتقــال بكامــل الفرقــة الــى املوقــع احملــدد مــن قبــل املــروج‪........‬‬\n      ‫وعنــد الوصــول الــى منــزل املــروج ‪ ........‬خــرج شــخص مــن بــاب املنــزل‬\n      ‫يرتــدي الــزي الرياضــي وأحتــك بالســيارة التــي يســتقلها املصــدر والفــرد‬\n      ‫املكلــف وســلمه املصــدر املبلــغ املرقــم وســلم املــروج‪ ........‬للمصــدر مــا‬\n      ‫عــدده (‪ )5‬خمــس حبــات حتمــل عالمــة الــروش احملظــورة وكان ذلــك‬\n      ‫علــى مــرأى مــن الفــرد املكلــف مبرافقــه املصــدر وعندهــا دخــل املــروج‬\n      ‫منزلــه ولــم يتــم القبــض عليــه الشــتراط املصــدر ذلــك مســبق ًا فتــم رصــد‬\n      ‫منــزل املــروج علــى فتــرات متفاوتــة ولــم يخــرج املذكــور مــن منزلــه و‬\n\n\n‫‪297‬‬\n\f‫بتاريــخ ‪1432/4/22‬ه ـ مت دخــول منــزل املــروج (بعــد اخــذ االذن الــازم)‬\n‫وبدخــول املجلــس كانــت تنبعــث منــه رائحــة احلشــيش املخــدر وعثــر بــه‬\n‫علــى و و بتفتيــش املجلــس عثــر بــن أقــدام علــى (‪ )3‬ثــاث قطــع مختلفــة‬\n‫االحجــام يشــتبه ان تكــون مــن مــاده احلشــيش املخــدر بلــغ وزنهــا جميعـ ًا‬\n‫(‪ )21‬إحــدى وعشــرين جرامـ ًا وكذلــك عثــر بــن و علــى ثــاث ســجائر‬\n‫مســتخدمة يشــتبه أن يكــون تبغهــا ممزوجـ ًا مبــاده احلشــيش املخــدر بلــغ‬\n‫وزنهــا (‪ )3‬ثــاث جرامــات وكذلــك علــى فتــات تبــغ يشــتبه ان يكــون‬\n‫ممــزوج مبــادة احلشــيش املخــدر بلــغ وزنــه (‪ )1,8‬جرامـ ًا وثمانيــة اعشــار‬\n‫اجلــرام وبالدخــول الــى احــد غــرف النــوم مت القبــض علــى املــروج‪ ........‬ومت‬\n‫التعــرف عليــه مــن قبــل الفــرد املكلــف مبرافقــه املصــدر وعثــر معــه على‬\n‫هاتــف جــوال مــن نــوع (‪ )....‬ويحمــل الرقــم املصنعــي () وهــو اجلــوال الــذي‬\n‫مت مــن خاللــه امتــام عمليــة التفــاوض علمــا بانــه لــم يعثــر معــه علــى املبلــغ‬\n‫املرقــم وبتفتيــش غرفــة نــوم‪ ........‬عثــر داخــل أحــد االدراج علــى علبــة‬\n‫روش حتــوي بداخلهــا علــى مــا عــدده (‪ )38‬ثمــان وثالثــون حبــه حتمــل‬\n‫عالمــه الــروش احملظــورة وكذلــك عثــر علــى قطعــه يشــتبه أن تكــون‬\n‫مــن احلشــيش املخــدر بلــغ وزنهــا (‪ )4.8‬أربعــة جرامــات وثمانيــة أعشــار‬\n‫اجلــرام وبالدخــول الــى امللحــق اخلارجــي عثــر علــى خزنــة وبفتحهــا عثــر‬\n‫بداخلهــا علــى كيــس نايلــون مختــوم مصنعي ـ ًا يحــوي بداخلــه علــى مــا‬\n‫عــدده (‪ )1000‬ألــف حبــة حتمــل عالمــة الكبتاجــون احملظــور وكذلــك‬\n‫علــى قطعتــن يشــتبه أن تكــون مــن مــادة احلشــيش املخــدر بلــغ وزنهمــا‬\n‫جميعـ ًا (‪ )8.4‬ثمانيــة جرامــات وأربعــة أعشــار اجلــرام وكذلــك علــى مــا‬\n‫عــدده (‪ )80‬ثمانــون حبــة حتمــل اســم زنكــس احملظــورة وبســؤال‪ ........‬و‬\n‫عــن عائديــه مــا ضبــط بداخــل اخلزنــة أفادوا أنها تعــود ألخيهما املذكور‬\n\n\n                                                                                           ‫‪298‬‬\n\f      ‫‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي املرفــق رقــم (‪/4077‬س)‬\n      ‫لعام‪1432‬ه ـ احتــواء عينــه احلبــوب التــي حتمــل عالمــه الكبتاجــون‬\n      ‫لإلمفيتامــن وهــو مــن املــواد املنبهــة املدرجــة باجلــدول رقــم (‪ )2‬فئــة‬\n      ‫(ب) امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وايجابيــه‬\n      ‫عينــات القطــع املضبوطــة ومســتخلص التبــغ املضبــوط ومســتخلص‬\n      ‫التبــغ يف الثــاث ســجائر املســتخدمة للحشــيش وهــو مــن املــواد املخــدرة‬\n      ‫املدرجــة باجلــدول رقــم (‪ )1‬فئــة(أ) امللحــق بنظــام مكافحــة املخــدرات‬\n      ‫واملؤثــرات العقليــة واحتــواء احلبــوب املروجــة ملركــب البــروزوالم‬\n      ‫واحتــواء عينــه احلبــوب املضبوطــة التــي حتمــل عالمــة الزنكــس ملركب‬\n      ‫البــرازوالم واحتــواء عينــه احلبــوب املضبوطــة التــي حتمــل عالمــة الــروش‬\n      ‫ملركــب الكلونازيبــام وهــي مــن املــواد املهدئــة واملدرجــة باجلــدول‬\n      ‫رقــم (‪ )2‬فئــه (د) امللحــق بــذات النظــام‪ .‬وباســتجوابه اعتــرف بعائديــه‬\n      ‫(اخلزنــة) التجــوري لــه وان لهــا ارقــام ســريه ومفتــاح وال يفتحــه اال هــو‪.‬‬\n      ‫وباســتجواب‪ :........‬افــاد ان احلبــوب وجميــع مــا ضبــط داخــل (اخلزنــة)‬\n      ‫التجــوري عائــده للمذكــور كــون امللحــق والتجــوري (اخلزنــة ) تعــود‬\n      ‫لــه هــو الــذي يحمــل مفاتيحهــا‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن‬\n      ‫توجيــه االتهــام لــ‪ ........‬بحيــازة مــا عــدده (‪ )1000‬الــف حبــه مــن حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة وقطعتــن مــن احلشــيش املخــدر تزنــان‬\n      ‫(‪ )8.4‬ثمانيــة جرامــات واربعــه اعشــار اجلــرام ومــا عــدده (‪ )80‬ثمانــون‬\n      ‫حبــة مــن حبــوب الكلونازيبــام املهدئــة احملظــورة بقصــد الترويــج‬\n      ‫واالجتــار والتعاطــي املجــرم مبوجــب املــادة (الثالثــة) مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم (م‪)39/‬‬\n      ‫وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى مصــدر مــا ضبــط املعاقــب علــى‬\n\n\n‫‪299‬‬\n\f‫ذلــك شــرعاً‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪ -1 -:‬مــا تضمنــه محضــر‬\n‫القبــض املنــوه عنــه املرفــق لفــه رقــم ( )‪ -2 .‬مــا تضمنــه اعترافــه بعائديــه‬\n‫اخلزنــة لــه وان لهــا ارقــام ســريه ومفاتيــح وال يفتحهــا اال هــو املــدون علــى‬\n‫الصفحــة رقــم(‪ )3‬مــن دفتــر التحقيــق املرفــق لفــه رقــم ( ) ‪ -3‬مــا تضمنــه‬\n‫افــاده اخويــه مــن ان اخلزنــة عائــد ألخيهمــا املذكــور وانــه هــو الــذي‬\n‫يحمــل مفاتيحهــا املنــوه عنهــا املــدون علــى اللفــات رقــم (‪ -4 )28-24‬مــا‬\n‫تضمنــه التقريــر الكيميائــي الشــرعي املرفــق لفــه رقــم ( )‪ .‬وببحــث‬\n‫ســوابقه اتضــح وجــود ســابقتني االولــى حيــازة واســتعمال املخــدرات‬\n‫والثانيــة ترويــج املخــدرات مســجله عليــه حتــى تاريخــه وعثــر لــه علــى‬\n‫قضيــه مخــدرات االولــى برقــم (‪ )32/115/457‬واحيلــت الــى احملكمــة‬\n‫اجلزئيــة بالريــاض باخلطــاب رقــم (ه ـ ر‪ )39360/5/1‬يف ‪1432/4/17‬ه ـ‬\n‫والثانيــة برقــم (‪ )33/114/6‬واحيلــت الــى احملكمــة اجلزئيــة بالريــاض‬\n‫باخلطــاب رقــم (ه ـ ر‪ )17076/5/1‬يف ‪1433/2/10‬ه ـ ‪ .‬وحيــث إن مــا‬\n‫أق ــدم عل ــيه ال ــمذكور ف ــعل م ــحرم وم ــعاقب عليــه شــرع ًا ونظامـ ًا لــذا‬\n‫أطلــب إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪ -1 :‬بعقوبــة‬\n‫الســجن واجللــد والغرامــة املاليــة بحقــه وفقـ ًا للفقــرة االول مــن املادة (‪)38‬‬\n‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة املشــار اليــه واعمــال‬\n‫الفقــرة االولــى مــن املــادة (‪ )62‬مــن النظــام نفســه بحقــه لقــاء مــا اســند‬\n‫اليــه‪ -2 .‬منعــه مــن الســفر الــى خــارج اململكــة بعــد تنفيــذ عقوبــة ســجنه‬\n‫وفقـ ًا للفقــرة (األولــى) مــن املــادة (‪ )56‬مــن النظــام املشــار إليــه‪ -3.‬عقوبــة‬\n‫تعزيريــه بحقــه لقــاء تســتره علــى مصــدر مــا ضبــط‪ .‬هــذا وباســتجواب‬\n‫املدعــى عليــه فقــال مــا ذكــره املدعــي العــام يف دعــواه فغيــر صحيــح‬\n‫فلــم يعثــر يف اخلزنــة العائــدة لــي املوجــودة يف داخــل املنــزل علــى اي حبوب‬\n\n\n                                                                                          ‫‪300‬‬\n\f      ‫وال مخــدرات امنــا الــذي فيهــا مبلــغ مالــي وبعــض االوراق وال يوجــد يف‬\n      ‫منزلنــا وهــو منــزل والدنــا ســوى هــذه اخلزنــة العائــدة لي ولهــا مفتاح معي‬\n      ‫انــا فقــط ولهــا ارقــام ســرية لفتحهــا ال يعرفهــا وال يفتحهــا اال أنــا هــذا‬\n      ‫فطلبــت البينــة مــن املدعــي العــام علــى مــا جــاء يف دعــواه ضــد املدعــى‬\n      ‫عليــه فقــال لــدي البينــة مســتعد بإحضارهــا يف موعــد اجللســة القادمــة‬\n      ‫هــذا وبنــاء علــى ذلــك فقــد جــرى حتديــد موعــد الســتكمال النظــر يف‬\n      ‫هــذه الدعــوى يف يــوم الســبت املوافــق ‪1433/5/15‬ه ـ الســاعة العاشــرة‬\n      ‫صباحــا وجــرى ابــاغ املدعــي العــام واجلهــة املســؤولة عــن املدعــى عليــه‬\n      ‫بهــذا املوعــد إلحضــاره فيــه وعليــه فقــد رفعــت اجللســة وحصــل التوقيــع‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                       ‫حــرر يف ‪ 1433/05/08‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1433/5/15‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 :11‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وقــرر املدعــي العــام بقولــه اننــي لــم امتكــن مــن احضــار بينتــي‬\n      ‫يف هــذا اليــوم وذلــك لكــون الشــهود ملتحقــن بــدورات خــارج عملهــم‬\n      ‫وارغــب اعطائــي موعــدا أخــرى حتــى امتكــن مــن احضارهــم فيــه هــذا‬\n      ‫وبنــاء علــى ذلــك فقــد جــرى حتديــد موعــد الســتكمال النظــر يف هــذه‬\n      ‫الدعــوى يف يــوم االربعــاء املوافــق ‪1433/5/19‬ه ـ الســاعة احلاديــة عشــر‬\n      ‫والنصــف صباحــا وجــرى ابــاغ املدعــي العــام واجلهــة املســؤولة عــن‬\n      ‫املدعــى عليــه بهــذا املوعــد إلحضــاره فيــه وعليــه فقــد رفعــت اجللســة‬\n      ‫وحصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                              ‫وســلم‪ .‬حــرر يف ‪ 1433/05/15‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االربعــاء املوافــق ‪1433/5/19‬ه ـ‬\n\n\n‫‪301‬‬\n\f‫افتتحــت اجللســة الســاعة ‪ 1 :51‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه وقــرر املدعــي العــام بقولــه اننــي لــم امتكــن مــن احضــار البينــة‬\n‫يف هــذا اليــوم لكــون الشــهود مازالــوا ملتحقــن بــدورات خــارج‬\n‫عملهــم وارغــب اعطائــي موعــدا يف االســبوع القــادم حتــى يتــم التنســيق‬\n‫معهــم علــى احلضــور فيــه هــذا وبنــاء علــى ذلــك فقــد جــرى حتديــد‬\n‫موعــد الســتكمال النظــر يف هــذه الدعــوى يف يــوم االثنــن املوافــق‬\n‫‪1433/5/24‬ه ـ الســاعة العاشــرة صباحــا وجــرى ابــاغ املدعــي العــام‬\n‫واجلهــة املســؤولة عــن املدعــى عليــه بهــذا املوعــد إلحضــاره فيــه وعليــه‬\n‫فقــد رفعــت اجللســة وحصــل التوقيــع وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                         ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/05/19‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافق‪1433/05/24‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 :32‬وفيهــا حضــر املدعــي العــام وقــرر‬\n‫بقولــه إننــي لــم أمتكــن مــن إحضــار البينــة يف هــذا اليــوم لكــون الشــهود‬\n‫ملتحقــن بــدورات خــارج عملهــم ولكــن مت التنســيق معهــم علــى احلضــور‬\n‫يــوم الســبت القــادم وأرغــب أن يكــون موعــد اجللســة القادمــة يف ذلــك‬\n‫اليــوم هــذا وبنــاء علــى ذلــك فقــد جــرى حتديــد موعــد الســتكمال‬\n‫النظــر يف هــذه الدعــوى يف يــوم الســبت القــادم املوافــق ‪1433/5/29‬ه ـ‬\n‫الســاعة العاشــرة صباحــا وجــرى إبــاغ املدعــي العــام واجلهــة املســئولة‬\n‫عــن إحضــار املدعــى عليــه بهــذا املوعــد إلحضــاره فيــه وعليــه فقــد رفعت‬\n‫اجللســة وحصــل التوقيــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                    ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1433/05/25‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1433/05/29‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 :08‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n\n\n                                                                                     ‫‪302‬‬\n\f      ‫عليــه كمــا حضــر كل مــن ‪ ........‬ســعودي اجلنســية احلامــل لبطاقــة‬\n      ‫الهويــة الوطنيــة رقــم‪ ........‬و‪ ........‬ســعودي اجلنســية احلامــل لبطاقــة‬\n      ‫الهويــة الوطنيــة رقــم ‪ ........‬هــذا وبســؤال الشــاهد عــن عمــره وعملــه‬\n      ‫وصلتــه بأطــراف الدعــوى فقــال ابلــغ مــن العمــر (‪ )..‬عامــا واعمــل يف‬\n      ‫إدارة مكافحــة املخــدرات وال تربطنــي بأطــراف الدعــوى أي صلــه‬\n      ‫هــذا وبســؤاله عمــا لديــه مــن شــهاده فقــال بعــد مداهمتنــا للمنــزل الــذي‬\n      ‫يســكن فيــه اخــو املدعــى عليــه املــروج وبالدخــول للملحــق اخلارجــي‬\n      ‫الــذي يقــع خلــف املنــزل عثرنــا علــى خزنــه مقفلــه فتــم كســرها وعثرنــا‬\n      ‫بداخلهــا علــى كيــس نايلــون مختــوم مصنعــي بداخلــه حبــوب عددهــا‬\n      ‫ألــف حبــه وعلــى قطعتــن حشــيش تزنــان (‪8,4‬جــم) وعلــى ثمانــن حبــة‬\n      ‫زنكــس وســألنا شــقيقي املدعــى عليــه عــن عائديــة مــا ضبــط بداخــل‬\n      ‫اخلزنــة فأفادونــا أنهــا تعــود ألخيهــم املدعــى عليــه فتــم أخــذ اقــرار عليهــم‬\n      ‫بذلــك كمــا عثرنــا بداخــل اخلزنــة علــى صورة من بطاقــة أحوال املدعى‬\n      ‫عليــه هــذا مــا لــدي مــن شــهادة هــذا وبســؤال الشــاهد الثانــي عــن عمــره‬\n      ‫وعملــه وصلتــه بأطــراف الدعــوى فقــال ابلــغ مــن العمــر (‪ )..‬عامــا واعمــل‬\n      ‫يف إدارة مكافحــة املخــدرات وال تربطنــي بأطــراف الدعــوى أي صلــة‬\n      ‫هــذا وبســؤاله عمــا لديــه مــن شــهادة فقــال بعــد مداهمتنــا للمنــزل الــذي‬\n      ‫يســكن فيــه أخــو املدعــى عليــه املــروج وبالدخــول للملحــق اخلارجــي‬\n      ‫الــذي يقــع خلــف املنــزل عثرنــا علــى خزنــة مقفلــة فتــم كســرها وعثرنــا‬\n      ‫بداخلهــا علــى كيــس نايلــون مختــوم مصنعــي بداخلــه حبــوب عددهــا‬\n      ‫ألــف حبــة وعلــى قطعتــن حشــيش تزنــان (‪8,4‬جــم) وعلــى ثمانــن حبــة‬\n      ‫زنكــس وســألنا شــقيقي املدعــى عليــه وعــن عائديــة مــا ضبــط بداخــل‬\n      ‫اخلزنــة فأفادونــا أنهــا تعــود ألخيهــم املدعــى عليــه فتــم اخــذ اقــرار عليهم‬\n\n\n‫‪303‬‬\n\f‫بذلــك كمــا عثرنــا بداخــل اخلزنــة علــى صورة من بطاقــة أحوال املدعى‬\n‫عليــه هــذا مــا لــدي من شــهاده هذا وبعرض الشــاهدين وشــهادتهما على‬\n‫املدعــى عليــه فقــال امــا الشــاهدان فــا أعرفهمــا وأمــا شــهادتهما فغيــر‬\n‫صحيحــة ألن تلــك اخلزنــة كانــت داخــل الفلــة ولــم يكــن فيهــا حشــيش‬\n‫وال حبــوب وال صــورة مــن بطاقتــي امنــا كان فيهــا فلــوس فقــط وســبق‬\n‫ان اعتــرف اخــي عنــد الشــيخ احلبــوب لــه وحكمــه الشــيخ علــى ذلــك‬\n‫هــذا كمــا حضــر ‪ ........‬احلامــل لبطاقــة الهويــة الوطنية رقــم ‪ ........‬و‪........‬‬\n‫حامــل الســجل املدنــي رقــم ‪ ........‬فشــهدا بعدالــة الشــاهدين املذكوريــن‬\n‫بعاليــه هــذا ولتأمــل هــذه القضيــة فقــد جــرى حتديــد موعــد فقــد جــرى‬\n‫حتديــد موعــد الســتكمال النظــر يف هــذه الدعــوى يف يــوم األربعــاء‬\n‫املوافــق ‪1433/6/4‬ه ـ وجــرى ابــاغ املدعــي العــام واجلهــة املســؤولة عــن‬\n‫املدعــى عليــه بهــذا املوعــد إلحضــاره فيــه وعليــه فقــد رفعــت اجللســة‬\n‫وحصــل التوقيــع بــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/05/29‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1433/06/04‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 10 :43‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n‫عليــه فجــرى ســؤاله عــن القضيــة املســجون ألجلهــا فقــال هــي قضيــة‬\n‫حيــازة حبــوب لــدى الشــيخ القاضــي يف احملكمــة وحوكمــت عليهــا‬\n‫بالســجن ملــدة ســتة أشــهر ولــم تنتــه محكوميتــي وأعتقــد أن هــذا‬\n‫احلكــم قــد شــمل هــذه القضيــة وقضيــة حيــازة احلبــوب ألنــه ســألني‬\n‫عنهمــا هــذا وبنــاء علــى ذلــك فســيجري منــا مخاطبــة الشــيخ لإلفــادة عــن‬\n‫ذلــك وعنــد ورود اإلجابــة فســيتم طلــب املدعــى عليــه وإكمــال النظــر‬\n‫يف هــذه الدعــوى وعليــه فقــد رفعــت اجللســة وحصــل التوقيــع ‪ ،‬وبــاهلل‬\n\n\n                                                                                         ‫‪304‬‬\n\f      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                                 ‫يف ‪1433/06/04‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1433/06/21‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01 :34‬حيــث مت جــرى منــا طلــب املدعــى عليــه‬\n      ‫إلحضــاره يف هــذه اجللســة مــن قبــل ادارة الســجن اال انــه لــم يتــم احضــاره‬\n      ‫هــذا وبنــاء علــى ذلــك فقــد جــرى حتديــد موعــد بعــد غــد يف يــوم االثنــن‬\n      ‫املوافــق ‪1433/6/23‬ه ـ الســاعة العاشــرة صباحــا وجــرى ابــاغ اجلهــة‬\n      ‫املســؤولة عــن املدعــى عليــه بهــذا املوعــد إلحضــاره فيــه وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                      ‫‪ 1433/06/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ه ـ ففــي يــوم االثنــن املوافق‪1433/06/23‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 1 : 00‬وفيهــا حضــر املدعــي العــام امــا املدعى‬\n      ‫عليــه فلــم يتــم احضــاره رغــم طلبنــا احضــاره يف هــذا املوعــد مــن اداره‬\n      ‫الســجن وعليــه فقــد جــرى حتديــد موعــد يف يــوم غــد الثالثــاء املوافــق‬\n      ‫‪1433/6/24‬ه ـ الســاعة العاشــرة صباحــا وجــرى ابــاغ املدعــي العــام‬\n      ‫واجلهــة املســؤولة عــن املدعــى عليــه بهــذا املوعــد إلحضــاره فيــه وعليــه‬\n      ‫فقــد رفعــت اجللســة وحصــل التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/06/23‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء املوافــق‪ 1433/06/24‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 :53‬وفيهــا حضــر املدعــي العــام واملدعــى‬\n      ‫عليــه وقــد وردنــا مــن فضيلــه القاضــي بهــذه احملكمــة صــورة مصدقــه‬\n      ‫مــن القــرار الصــادر منــه برقــم ‪ 3387151‬يف ‪1433/2/16‬ه ـ ومبطالعته‬\n      ‫وجدتــه تضمــن دعــوى املدعــي العــام ضــد املدعــى عليــه باتهامــه بحيــازة‬\n\n\n‫‪305‬‬\n\f‫خمســن حبــة زنكــس وقطعــه حشــيش تــزن (‪6,7‬جــم) عثــر عليهــا‬\n‫بداخــل درج ســيارته وقيادتــه للســيارة حتــث تأثيــر احلبــوب وتعاطــي‬\n‫احلبــوب احملظــورة وشــربه للمســكر وحيازتــه وصــدم ســيارة الدوريــة‬\n‫وتاريخهــا ‪1433/1/2‬ه ـ ومت احلكــم عليــه فيها بتاريــخ ‪1433/2/16‬هـ‬\n‫وهــذه بخــاف الدعــوى املقامــة ضــده لدينــا مضمونــا وتاريخــا وعليــه‬\n‫فقــد جــرى ســؤال املدعــى عليــه عــن وجــود ثــاث ســوابق مســجلة‬\n‫عليــه اثنتــان حيــازة واســتعمال مخــدرات والثالثــة ترويــج مخــدرات‬\n‫فقــال هــذا صحيــح هــذا كمــا جــرى االطــاع علــى املعاملــة ووجــدت‬\n‫التقريــر الكيميائــي الشــرعي رقــم ‪/4077‬س وقــد تضمــن احتــواء‬\n‫عينــة احلبــوب لإلمفيتامــن وايجابيــة عينــة القطــع للحشــيش واحتــواء‬\n‫احلبــوب التــي حتمــل عالمــه الزنكــس للبرازوالم‪.‬أه ـ فنظــرا ملــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وحيــث انكــر املدعــى عليــه مــا جــاء يف دعــوى‬\n‫املدعــي العــام ولكــن حيــث افــاد لدينــا بــان اخلزنــة املذكــورة عائــده لــه‬\n‫ولهــا مفتــاح معــه فقــط ولهــا ارقــام ســريه لفتحهــا ال يعرفهــا وال يفتحهــا‬\n‫اال هــو وحيــث شــهدت البينــة املعدلــة شــرعا مــن العثــور علــى الــف حبــه‬\n‫محظــورة وعلــى قطعتــي حشــيش تزنــان (‪8,4‬جــم) وعلــى ثمانــن حبــه‬\n‫زنكــس داخــل تلــك اخلزنــة والعثــور ايضــا علــى صــوره مــن بطاقــه احــوال‬\n‫املدعــى عليــه فقــد ثبــت لــدي ادانــه املدعــى عليــه بحيــازة الــف حبــه‬\n‫محظــورة كبتاجــون و ثمانــن حبــه محظــورة زنكــس وعلــى قطعتــي‬\n‫حشــيش تزنــان (‪8,4‬جــم) لغيــر قصــد االجتــار أو الترويــج أو التعاطــي‬\n‫وحيــث يغلــب علــى الظــن انهــا لإلجتــار والترويــج فقــد حكمــت عليــه‬\n‫تعزيــرا باحلــد االعلــى مــن العقوبــة بســجنه ملــده خمــس ســنوات تبــدأ بعــد‬\n‫انتهــاء محكوميتــه يف القضيــة املســجون ألجلهــا وبجلــده خمســمائة‬\n\n\n                                                                                      ‫‪306‬‬\n\f      ‫جلــده مفرقــه علــى عشــر فتــرات ْ متســاوية بــن كل فتــره واخــرى‬\n      ‫اســبوعان لقــاء ذلــك ولقــاء ســوابقه وتســتره وبدفــع غرامــه قدرهــا ثالثــة‬\n      ‫االف ريــال ومبنعــه مــن الســفر خلــارج اململكــة ملــده خمــس ســنوات بعــد‬\n      ‫تنفيــذ عقوبــة ســجنه متشــيا مــع املادتــن (‪ )56-39‬مــن نظــام مكافحــه‬\n      ‫املخــدرات هــذا وبعــرض ذلــك علــى املدعــى عليــه فقــرر عــدم قناعتــه‬\n      ‫باحلكــم كمــا قــرر بقولــه ال ارغــب يف اســتالم نســخه مــن قــرار احلكــم‬\n      ‫لالعتــراض عليــه وارغــب بتدويــن اعتراضــي يف ضبــط القضيــة وهــو ان‬\n      ‫احلبــوب املذكــورة لــم تكــن يف اخلزنــة امنــا يوجــد يف اخلزنــة مبلــغ مالــي‬\n      ‫فقــط واحلكــم كثيــر واخــي ســبق ان اعتــرف ان احلبــوب لــه كمــا قــرر‬\n      ‫املدعــي العــام عــدم قناعتــه باحلكــم معتبــرا الئحــة الدعــوى الئحــة‬\n      ‫اعتراضيــه علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                        ‫وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/06/24‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم االربعــاء املوافــق ‪ 1433/12/29‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 11 :30‬بنــاء علــى قرار الدائــرة اجلزائية الرابعة‬\n      ‫مبحكمــه االســتئناف بالريــاض رقــم ‪ 33407634‬يف ‪1433/9/10‬ه ـ‬\n      ‫واملتضمــن انــه لوحــظ مــا يلــي ‪ -1‬اشــار املدعــي العــام بدعــواه أنــه عثــر‬\n      ‫للمدعــى عليــه علــى قضيتــن مخــدرات األولــى برقــم ‪32/115/457‬‬\n      ‫والثانيــة برقــم ‪ 33/114/6‬وانهمــا احيلتــا للمحكمــة اجلزئيــة وحيــث‬\n      ‫تبــن ان الثانيــة صــدر بهــا القــرار رقــم ‪ 3387151‬يف ‪1433/2/16‬ه ـ من‬\n      ‫الشــيخ ‪ ........‬ولــم يجــد ان فضيلتــه استفســر عــن مصيــر القضيــة الثانيــة‬\n      ‫ومــا مت بخصوصهــا وال بــد مــن ذلــك واذا صــدر بخصوصهــا قــرار فــا‬\n      ‫بــد مــن إرفــاق صــورة منــه مصدقــة مبــا عليــه مــن تظهيــرات االســتئناف‬\n      ‫‪-2‬عنــد اصــدار فضيلتــه للقــرار لــم يطبــق فضيلتــه املــادة رقــم (‪ )164‬مــن‬\n\n\n‫‪307‬‬\n\f‫نظــام املرافعــات بخصــوص اختصــار القــرار‪ .‬فعلــى فضيلتــه مالحظــه‬\n‫مــا ذكــر واجــراء مــا يلــزم نحوهــا واحلــاق ملخــص مــا يجريــه يف الضبــط‬\n‫والقــرار ومــن ثــم اعــاده املعاملــة إلكمــال الزمهــا حســب التعليمــات‪ .‬أهــ‪.‬‬\n‫واجيــب اصحــاب الفضيلــة انــه بالنســبة للملحوظــة االولــى فقــد جرى منا‬\n‫مخاطبــه فضيلــه رئيــس هــذه احملكمــة بخطابنــا رقــم ‪33/2082717‬‬\n‫يف ‪1433/11/27‬ه ـ لالستفســار عــن القضيــة رقــم ‪32/ 115 / 457‬‬\n‫واحملالــة مــن االدعــاء العــام باخلطــاب رقــم ه ـ ر ‪ 39360/5/1‬يف‬\n‫‪1432/4/17‬ه ـ فوردنــا شــرح فضيلتــه علــى خطــاب مديــر االتصــاالت‬\n‫اإلداريــة رقــم ‪ 33/2082717‬يف ‪1433/12/27‬ه ـ واملتضمــن ان مت‬\n‫البحــث عــن اخلطــاب املوجهــة لنــا مــن قبــل االدعــاء العــام رقــم ‪39360‬‬\n‫يف ‪1433/4/17‬ه ـ ولــم جنــد رقــم للمعاملــة يف النظــام‪ .‬أهــ‪ .‬وبالنســبة‬\n‫للملحوظــة الثانيــة ان مــا حصــل قــد وقــع ســهوا وســيتم مالحظــه ذلــك‬\n‫مســتقبال وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم‪ .‬حــرر يف ‪1433/12/29‬ه ـ ‪ 0‬احلمــد هلل وحــده وبعــد‬\n‫ففــي يــوم الســبت املوافــق‪ 1434/04/27‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 11:22‬بنــاء علــى قــرار الدائــرة اجلزائيــة الرابعــة مبحكمــة االســتئناف‬\n‫بالريــاض رقــم ‪ 3441175‬وتاريــخ ‪1434/02/19‬ه ـ املتضمــن انــه لوحظ‬\n‫أن اجابــة فضيلتــه علــى الفقــرة االولــى مــن قــرار الدائــرة غيــر مالقيــة‬\n‫فقــد طلبنــا مــن فضيلتــه االستفســار عــن مصيــر القضيــة الثانيــة رقــم‬\n‫‪ 33/114/6‬الصــادر بهــا القــرار الشــرعي رقــم ‪ 3387151‬وتاريــخ‬\n‫‪1433/2/16‬ه ـ أ‪.‬ه ـ هــذا وبنــاء علــى ذلــك فقــد جــرى منــا مخاطبــة‬\n‫فضيلــة رئيــس هــذه احملكمــة لالستفســار عــن ذلــك بخطابنــا رقــم‬\n‫‪ 34755015‬وتاريــخ ‪1434/3/25‬ه ـ فوردنــا شــرح فضيلتــه املــؤرخ يف‬\n\n\n                                                                                     ‫‪308‬‬\n\f      ‫‪1434/4/27‬ه ـ املبنــي علــى خطــاب فضيلــة القاضــي رقــم ‪34942191‬‬\n      ‫وتاريــخ ‪1434/4/16‬ه ـ املتضمــن أن املعاملــة واوراق القضيــة صــدرت‬\n      ‫لألمــارة برقــم ‪ 33291834‬يف ‪1434/2/23‬ه ـ وبــاهلل التوفيــق ‪ ،‬وصلــى‬\n      ‫اهلل على نبينا محمد وعلى آله وصحبه وســلم‪ .‬حرر يف ‪1434/04/27‬‬\n      ‫ه ـ احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق ‪ 1434/07/26‬ه ـ‬\n      ‫افتتحــت اجللســة بنــاء علــى قــرار الدائــرة اجلزائيــة الرابعــة مبحكمــه‬\n      ‫االســتئناف بالريــاض رقــم ‪ 34246217‬يف ‪1434/6/19‬ه ـ واملتضمــن‬\n      ‫انــه لوحــظ مــا يلــي ‪ -1‬ذكــر املدعــى عليــه يف معــرض اجابتــه علــى‬\n      ‫شــهاده الشــاهدين صحيفــه (‪ )8‬مــن القــرار ان اخيــه اعترف لدى فضيله‬\n      ‫الشــيخ بــان احلبــوب لــه وحكــم علــى اخيــه بنــاء علــى ذلــك واكــد هــذا‬\n      ‫الــكالم عنــد عــرض احلكــم عليــه ولــم جنــد ان فضيلتــه حتقــق مــن‬\n      ‫ذلــك ملــا لــه مــن اثــر يف احلكــم ‪ -2‬طالــب املدعــي العــام مجــازاه املدعــى‬\n      ‫عليــه مبــا تضمنتــه املــادة رقــم (‪ )38‬مــن نظــام املخــدرات ولــم جنــد ان‬\n      ‫فضيلتــه تعــرض لذلــك بشــيء يف احلكــم وال بــد مــن ذلك‪.‬أه ـ هــذا‬\n      ‫وبنــاء علــى ذلــك فســيجري منــا مخاطبــة فضيلــه رئيــس هــذه احملكمــة‬\n      ‫بتزويدنــا بصــوره مــن القــرار الشــرعي الصــادر ضــد اخــي املدعــى عليــه‬\n      ‫ثــم وردنــا شــرح مديــر الوثائــق باحملكمــة وبرفقــه صــورة مصدقــه‬\n      ‫مــن القــرار الشــرعي رقــم ‪ 32291988‬يف ‪1432/11/4‬ه ـ الــذي بــدأه‬\n      ‫الشــيخ واكملــه الشــيخ وقــد جــرى االطــاع عليــه ولــم اجــد فيــه ان اخــا‬\n      ‫املدعــى عليــه ذكــر بــان احلبــوب محــل الدعــوى لــه بــل ذكــر ان احلبــوب‬\n      ‫تعــود ألخيــه حســبما يتضــح مــن صحيفــه (‪ )2‬الســطر اخلامــس عشــر‬\n      ‫والســادس عشــر ومت احلكــم عليــه وعلــى اخيهــم بتهمــه حيــازة تلــك‬\n      ‫احلبــوب وهــذا ال مينــع مــن احلكــم يف هــذه القضيــة علــى اخيهــم الحتمــال‬\n\n\n‫‪309‬‬\n\f‫اشــتراكهم جميعــا يف حيــازة تلــك احلبــوب ال ســيما انهــم منكــرون‬\n‫حليازتهــا وبالنســبة للملحوظــة الثانيــة فإكمــاال ملــا حكمــت بــه يف هــذه‬\n‫الدعــوى فقــد صرفــت النظــر عــن مطالبــه املدعــي العــام بالعقوبــات‬\n‫الــواردة يف املــادة (‪ )38‬مــن نظــام املخــدرات وبــه حكمــت لعــدم ثبــوت‬\n‫موجبــه هــذا وبعــرض ذلــك علــى املدعــي العــام فقــرر بقولــه اننــي مــا‬\n‫زلــت معترضــا علــى احلكــم معتبــرا الئحــة الدعــوى الئحــة اعتراضيــه‬\n‫علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                 ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/08/13‬ه ـ‬\n‫احلمــد اهلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n‫احملكمــة اجلزائيــة بالريــاض برقــم ‪ 341584161‬وتاريــخ ‪1434/9/1‬ه ـ‬\n‫املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ (‪)....‬‬\n‫املســجل برقــم (‪ ).....‬وتاريــخ ‪1433/6/24‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد (‪ )....‬التهامــه بقضيــة مخــدرات املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل بــه وحيــث ســبق دراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه‬\n‫ـاء علــى قرارنــا رقــم ‪ 34246217‬وتاريــخ‬      ‫بالقــرار وصــورة ضبطــه بنـ ً‬\n‫‪1434/6/19‬ه ـ تقــرر الدائــرة املصادقــة علــى احلكــم بعــد اإلجــراء‬\n‫األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪310‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":295,"source_page_end":310,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"87efaf3feba17eefa0b37a279ce13348fb90084c48a9bf2a7261400772ef1819","normalized_text_hash":"e3a8f9bbda949a3c3e95c51bd1803c00dff509e2f91f120e2b51b78ec13c6da2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p295-33314559"},{"id":"526b53ec-8f61-52b2-bded-12451e78547d","document_type":"judgment","category":"judicial","subcategory":"general","title":"ديبريبان -حيازة حبوب لغرض العاج مبوجب وصفة طبية - حيازة حبوب مسكنة .","document_number":"33410082","case_number":"33294088","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/09","year":"1434","subject":"ديبريبان -حيازة حبوب لغرض العاج مبوجب وصفة طبية - حيازة حبوب مسكنة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪33410082 :‬تاريخه ‪1433/12/09 :‬هـ‬\n                          ‫رقم القضية ‪33294088 :‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‬\n                 ‫‪ 3417543:‬تاريخه ‪1434/04/01:‬هـ‬\n\n\n       ‫حيــازة حبــوب الترامــادول ـ حيــازة حبــوب تامــول اكــس ـ حيــازة حبــوب‬\n       ‫ديبريبــان ‪ -‬حيــازة حبــوب لغــرض العــاج مبوجــب وصفــة طبيــة ‪-‬‬\n                                                        ‫حيــازة حبــوب مســكنة ‪.‬‬\n\n\n\n\n                       ‫األصل يف املسلم البراءة ( قاعدة ‪ :‬األصل براءة الذمة )‪.‬‬\n\n\n\n\n       ‫توجيــه االتهــام للمدعــى عليــه املقيــم بتلقــي حبــوب محظــورة وهــي‬\n       ‫الترامــادول وحبــوب تامــول إكــس وحبــوب ديبريبــان بقصــد اســتعمالها‬\n       ‫حيــث مت االشــتباه بقــدوم وافــد مــن منفــذ املطــار‪ ،‬وبتفتيشــه عثــر داخــل‬\n       ‫امتعتــه علــى عــدد ثالثــن حبــة مــن حبــوب الترامــادول احملظــورة وعــدد‬\n       ‫أربــع حبــات مــن حبــوب تامــول إكــس وعــدد خمــس وأربعــن حبــة مــن‬\n       ‫حبــوب ديبريبــان‪ ،‬مت القبــض عليــه وأفــاد بــأن تلــك احلبــوب عائــدة‬\n       ‫لصديقــه (املدعــى عليــه )‪ ،‬مت إحضــاره و صــادق علــى مــا جــاء يف أقــوال‬\n       ‫الوافــد‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند للمدعــى عليــه واحلكــم‬\n       ‫عليــه بالســجن واإلبعــاد وفــق املادتــن (‪ )1/41‬و (‪ )2/56‬مــن نظــام‬\n       ‫مكافحــة املخــدرات ـ صــادق املدعــى عليــه علــى مــا جــاء يف الدعــوى‪،‬‬\n\n‫‪311‬‬\n\f‫دفــع املدعــى عليــه بــأن هــذه احلبــوب لالســتعمال الطبــي‪ ،‬أبــرز املدعــى‬\n‫عليــه وصفــة طبيــة‪ ،‬صــدر التقريــر الكيميائــي الشــرعي املتضمــن بــأن‬\n‫احلبــوب املذكــورة مــن أنواع مســكنات األلم القــوي ذات التأثير املخدر‬\n‫التــي تســتخدم يف بعــض احلــاالت الطبيــة‪ ،‬صــدر احلكــم بصــرف النظــر‬\n   ‫عــن دعــوى املدعــي العــام ـ صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة باملدينــة املنــورة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة‬\n‫املنــورة برقــم ‪ 33294088‬وتاريــخ ‪1433/04/27‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 33798874‬املتضمنــة دعــوى املدعــى العــام ‪..........‬وفيهــا أدعــى‬\n‫علــى ‪.......... /‬مصــري اجلنســية مبوجــب اإلقامــة رقــم ‪..........‬حيــث انــه‬\n‫بتاريــخ ‪1432/12/27‬ه ـ واثنــاء قــدوم املدعــو ‪.......... /‬مــن منفــذ مطــار‬\n‫االميــر عبداحملســن مبحافظــة ينبــع مت االشــتباه بــه وعنــد تفتيشــه عثــر‬\n‫داخــل أمتعتــه علــى عــدد ثالثــن حبــة مــن حبــوب الترامــادول احملظــورة‬\n‫وعــدد اربــع حبــات مــن حبــوب ( تامــول اكــس ) وعــدد خمســة وأربعــن‬\n‫حبــة ( ديبريبــان ) يشــتبه أنهــا محظــورة فتــم القبــض عليــه وأفــاد بــأن‬\n‫تلــك احلبــوب عائــدة لصديقــة املتهــم املذكــور أعــاه والــذي مت احضــاره‬\n‫والقبــض عليــه واثبــت التقريــر الكيميائــي الشــرعي رقــم (‪ )..........‬لعــام‬\n‫‪1433‬ه ـ الصــادر مــن مركــز الســموم والكيميــاء الشــرعية مبنطقــة‬\n‫املدينــة املنــورة ايجابيــة العينــة لعقــار الترامــادول وهــو مــن املــواد املخــدرة‬\n‫اخلاضعــة للرقابــة وقــد حفــظ االتهــام بحــق املدعــو ‪.......... /‬ثــم انتهــى‬\n\n                                                                                            ‫‪312‬‬\n\f      ‫التحقيــق مــع ‪.......... /‬إلــى اتهامــه بتلقــي حبــوب محظــورة بقصــد‬\n      ‫اســتعمالها وذلــك ملــا جــاء يف اقوالــه و ملــا جــاء مبحضر القبــض و التقرير‬\n      ‫الكيميائــي الشــرعي وحيــث إن مــا قــدم عليــه املذكــور فعــل محــرم‬\n      ‫ومعاقــب عليــه نظامـ ًا اطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة‬\n      ‫الســجن الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن نظــام مكافحــة‬\n      ‫املخــدرات وعقوبــة اإلبعــاد عــن البــاد الفقــرة (‪ )2‬مــن املــادة (‪ )56‬مــن‬\n      ‫النظــام نفســه هكــذا ادعــي وبــاهلل التوفيــق ثــم جــرى ســؤال املدعــى‬\n      ‫عليــه عمــا جــاء بدعــوى املدعــى العــام فأجــاب معترف ـ ًا بتلقيــه للحبــوب‬\n      ‫املنــوه عنهــا بالئحــة الدعــوى وذلــك عــن طريــق صديقــه ‪........../‬وذكــر‬\n      ‫ان هــذه احلبــوب صرفــت لــه عــن طريــق وصفــة طبيــة يف بــاده وأبــرز‬\n      ‫هــذه الوصفــة وانــه يعانــي مــن الــم يف ظهــره فصــرف لــه الترامــادول و‬\n      ‫التامــول اكــس كمــا ذكــر ان الــدواء االخــر املســمى ( ديبريبــان )‬\n      ‫صــرف لــه بوصفــة طبيــة لعــاج ضعــف جنســي عنــده حيــث يســتخدم‬\n      ‫هــذا العــاج لهــذا املــرض وأنــه زوجتــه تقيــم معــه يف هــذه البــاد وقــال‬\n      ‫انــه ال يعلــم بــأن هــذه االدويــة محظــورة يف اململكــة العربيــة الســعودية‬\n      ‫هكــذا اجــاب ثــم جــرى االطــاع علــى أوراق املعاملــة فوجــد مــن ضمنها‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم ‪..........‬لعــام ‪1433‬ه ـ املتضمــن‬\n      ‫ايجابيــة العينــة املضبوطــة لعقــار الترامــادول كمــا جــرى االطــاع علــى‬\n      ‫الوصفــة الطبيــة التــي ارفقهــا املدعــى عليــه املتضمنــة شــرح الدكتــور‬\n      ‫‪..........‬أحــد اطبــاء وجراحــة العظــام يف دولــة مصــر وفيهــا صــرف حبــوب‬\n      ‫الترامــادول للمدعــى عليــه كمــا جــرى االطــاع علــى االفــادة الطبيــة‬\n      ‫الصــادرة مــن مستشــفى امللــك فهــد باملدينــة املنــورة برقــم ‪..........‬وتاريــخ‬\n      ‫‪1433/4/12‬ه ـ التــي تفيــد بــأن حبــوب الترامــادول هــي مــن انــواع‬\n\n\n‫‪313‬‬\n\f‫مســكنات االلــم القــوي ذات التأثيــر املخــدر التــي تســتخدم يف بعــض‬\n‫االحيــان حلــاالت الكســور ومــا بعــد العمليــات اجلراحيــة باالضافــة‬\n‫الــى اســتخدامات اخــرى كمســكن قــوي لأللــم ‪ ،‬وعليــه صــدر منــا‬\n‫مــا نصــه بنــاء علــى الدعــوى واإلجابــة وعلــى مــا جــاء بــأوراق املعاملــة‬\n‫والوصفــة الطبيــة وإفــادة مستشــفى امللــك فهــد املتضمنــة ان هــذه املــادة‬\n‫تســتخدم ال غــراض طبيــة ولعــدم ثبــوت اســتخدامها لغــرض ســيء‬\n‫ولكــون االصــل يف املســلم البــراءة فقــد حكمــت بصــرف النظــر عــن‬\n‫دعــوى املدعــى العــام فقــرر املدعــى عليــه قناعتــه باحلكــم وبعرضــه علــى‬\n‫املدعــى العــام قــرر اعتراضــه علــى احلكــم بالئحــة وصلــى واهلل وســلم‬\n       ‫علــى نبينــا محمــد و علــى الــه وصحبــه حــرر يف ‪1433/09/12‬هــ‪.‬‬\n‫بتاريــخ ‪1434/1/10‬ه ـ وردت املعاملــة املتعلقــة بدعــوى املدعــى العــام‬\n‫ضد‪........../‬مــن محكمــة االســتئناف مبكــة املتضمــن انــه بدراســة‬\n‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر إعادتهــا لفضيلــة‬\n‫حاكمهــا ملالحظــة أن الالئحــة املعــدة مــن املدعــى العــام لــم يجــرى‬\n‫االطــاع عليهــا مــن حاكــم القضيــة والبــد منــه واهلل املوفــق وبنــاء عليــه‬\n‫ولوجاهــة مــارآه أصحــاب الفضيلــة فإنــه جــرى االطــاع علــى الالئحــة‬\n‫االعتراضيــة أملقدمــه مــن املدعــى العــام ولــم يوجــد بهــا مايلفــت النظــر‬\n‫هــذا وأســال اهلل أن يلهمنــا الصــواب وصلــى اهلل وســلم علــى نبينــاء‬\n              ‫محمــد وعلــى الــه وصحبــه وســلم حــرر يف ‪1434/1/12‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد‬\n‫فبتاريــخ ‪1434/02/10‬ه ـ وردت املعاملــة مــن محكمــة االســتئناف‬\n‫املتعلقــة بدعــوى املدعــى العــام ضــد ‪..........‬مشــفوعة بقــرار املالحظــة‬\n‫رقــم ‪ 3425105‬وتاريــخ ‪1434/01/27‬ه ـ املتضمــن أنــه بدراســة القــرار‬\n\n\n                                                                                    ‫‪314‬‬\n\f      ‫وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا لفضيلة‬\n      ‫حاكمهــا ملالحظــة أن مــا حكــم بــه ناظــر القضيــة يف غيــر محلــه‬\n      ‫فاملدعــى عليــه اعتــرف بتلقيــه هــذه احلبــوب لقصــد اســتعمالها وهــي‬\n      ‫ممنوعــة مبوجــب نظــام مكافحــة املخــدرات لــذا يلــزم مجازاتــه شــرع ًا‬\n      ‫بعــد إعــادة النظــر بحضــور الطرفــن واهلل املوفــق ‪ ،‬عليــه أجيب صاحبي‬\n      ‫الفضيلــة قضــاة محكمــة االســتئناف بــأن ماثبــت لــدي مــن تعاطــي‬\n      ‫املدعــى عليــه لنــوع هــذه احلبــوب كان لغــرض العــاج حســب الوصفــة‬\n      ‫الطبيــة املمنوحــة لــه مــن بلــده كمــا أنــه جــرى مخاطبــة مستشــفى امللــك‬\n      ‫فهــد لإلفــادة عــن نوعيــة هــذه احلبــوب ومــدى االســتفادة منهــا كعــاج‬\n      ‫فــوردت إفادتهــم رقــم ‪..........‬وتاريــخ ‪1433/4/12‬ه ـ تأيــد كالم املدعى‬\n      ‫عليــه مــن اســتخدامها للعــاج وعليــه فــا أرى تعزيــره الســتخدامه هــذه‬\n      ‫احلبــوب لغــرض العــاج هــذا مــن جهــة ومــن جهــة أخــرى فقــد ســبق وأن‬\n      ‫حكمــت بقضيتــن مماثلتــن لهــذه القضيــة بصــرف النظــر وجــرى‬\n      ‫تصديقهمــا مــن قبــل محكمــة االســتئناف بقراريهــا رقــم ‪33283800‬‬\n      ‫وتاريــخ ‪1433/6/7‬ه ـ ورقــم ‪ 3411732‬وتاريــخ ‪1434/1/13‬ه ـ لــذا‬\n      ‫فإننــي أرى أن مــا حكمــت بــه مناســب ًا واهلل أســأل أن يلهمنــا الصــواب‬\n      ‫إنــه ســميع الدعــاء وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                     ‫وســلم حــرر ‪1434/03/ 07‬هــ‪.‬‬\n      ‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ :‬نحــن رئيــس‬\n      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة اإلســتئناف مبنطقــة‬\n      ‫مكــة املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪33410082‬‬\n      ‫وتاريــخ ‪1433/9/12‬ه ـ الصــادر مــن فضيلــة الشــيخ‪........../‬القاضي‬\n      ‫باحملكمــة اجلزائيــة باملدينــة املنــورة ‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n\n\n‫‪315‬‬\n\f‫ضــد‪ ........../‬مصــري اجلنســية ورفيقــه ‪ ،‬املتهــم بتلقــي حبــوب محظــورة‬\n‫بقصــد اســتعمالها احملكــوم فيــه مبــا دون باطنــه املالحــظ عليــه بقــرار‬\n‫محكمــة االســتئناف رقــم ‪ 33475605‬وتاريــخ ‪1434/12/22‬ه ـ ‪.‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة تقــررت املوافقــة‬\n‫علــى احلكــم بعــد اإليضــاح األخيــر ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                                      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪،،،‬‬\n\n\n\n\n                                                                                    ‫‪316‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":311,"source_page_end":316,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"821d837e49b32c35f322c8f28f0c2b9d009cba432540da8d26dfa3907bc86908","normalized_text_hash":"88d027d4649acf4bb3649bd9ea450b65a62aba4b12f423f6e15c04c44823f160","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p311-33410082"},{"id":"c4eccd2d-5535-5a2b-a150-20eeea682576","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -مقيم بطريقة غير نظامية حيازة حبوب محظورة- تعاطي حبوب محظورة -إثبات اإلدانة باإلقرار -املتهم أجنبي - أسباب تخفيف العقوبة -التعزير بالسجن واجللد واإلبعاد.","document_number":"33409577","case_number":"33317638","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/12","year":"1434","subject":"مخدرات -مقيم بطريقة غير نظامية حيازة حبوب محظورة- تعاطي حبوب محظورة -إثبات اإلدانة باإلقرار -املتهم أجنبي - أسباب تخفيف العقوبة -التعزير بالسجن واجللد واإلبعاد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33409577 :‬تاريخه ‪1433/09/12:‬هـ‬\n                          ‫رقم القضية ‪33317638 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3469582‬تاريخه‪1434/05/28:‬هـ‬\n\n\n       ‫مخــدرات‪ -‬مقيــم بطريقــة غيــر نظاميــة ـ حيــازة حبــوب محظــورة‪-‬‬\n       ‫تعاطــي حبــوب محظــورة‪ -‬إثبــات اإلدانــة باإلقــرار ‪ -‬املتهــم أجنبــي ‪-‬‬\n           ‫أســباب تخفيــف العقوبــة‪ -‬التعزيــر بالســجن واجللــد واإلبعــاد‪.‬‬\n\n\n\n\n       ‫‪ -1‬قولــه تعالــى { َو َت َعا َو ُنــو ْا َع َلــى ا ْلبـ ِّـر َوال َّت ْق ـ َوى َو َال َت َعا َو ُنــو ْا َع َلــى ا ِإل ْثـ ِـم‬\n                                                                                                                            ‫َوا ْل ُعــدْ َوان }‬\n       ‫‪ -2‬مــن مقاصــد الشــريعة ‪ :‬حفــظ الضروريــات اخلمــس ومنهــا حفــظ‪:‬‬\n                                                                                                                     ‫النفــس والعقــل ‪.‬‬\n                   ‫‪ -3‬املواد (‪ )38‬و (‪ )53‬و (‪ )56‬و (‪ )60‬من نظام مكافحة املخدرات ‪.‬‬\n\n\n\n\n       ‫توجيــه االتهــام للمدعــى عليــه مقيــم بطريقــة غيــر نظاميــة بحيــازة (‪)361‬‬\n       ‫حبــة مــن احلبــوب احملظــورة بقصــد الترويــج والتعاطــي وتعاطيــه لهــذه‬\n       ‫احلبــوب‪ ،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل الضبــط اإلداري‬\n       ‫حليازتــه يف جيــب بنطالــه األميــن الســفلي كيسـ ًا بداخلــه (‪ )361‬حبــة مــن‬\n       ‫حبــوب اإلمفيتامــن‪ ،‬باســتجواب املدعــى عليــه أقــر بحيــازة هــذه احلبــوب‬\n       ‫بقصــد التعاطــي وتعاطيــه لهــا بالســابق‪ ،‬طلــب املدعــي العــام إثبــات مــا‬\n       ‫أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة‬\n\n‫‪317‬‬\n\f‫واإلبعــاد‪ ،‬أقــر املدعــى عليــه مبــا نســب إليــه‪ ،‬صــدر احلكــم بإثبــات‬\n‫إدانــة املدعــى عليــه مبــا نســب إليــه وتعزيــره بالســجن واجللــد والغرامــة‬\n                     ‫واإلبعــاد‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم ‪33317638‬‬\n‫وتاريــخ ‪1433/05/08‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33847511‬وتاريــخ‬\n‫‪1433/05/04‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/07/15‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 15‬وفيهــا حضــر املدعــي العــام ‪.........‬ســعودي‬\n‫اجلنســية حامــل بطاقــة أحــوال رقــم (‪ ).........‬واملكلــف بالعمــل لدينــا‬\n‫مبوجــب خطــاب التكليــف ذو الرقــم (‪ ).........‬وتاريــخ ‪1430/12/29‬ه ـ‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام‬      ‫وقــرر دعــواه قائ ـ ً‬\n‫مبحافظــة جــدة أدعــى علــى ‪ 41،......... :‬عام ـاً‪ ،‬مينــي اجلنســية مبوجــب‬\n‫البطاقــة البديلــة املؤقتــة رقــم ‪ .........‬الصــادرة مــن مكافحــة املخــدرات‬\n‫مبحافظــة جــدة بتاريــخ ‪1433/4/4‬ه ـ ‪ ،‬يقيــم بطريقــة غيــر نظاميــة‪،‬‬\n‫عاطــل ‪،‬متعلــم‪ ،‬متــزوج‪ ،‬موقـ ــوف بالســجن الع ـ ـ ــام مبحافظ ـ ـ ــة ج ـ ـ ــدة‬\n‫مبوجــب أمــر متديــد التوقيــف رقــم‪ .........‬وتاريــخ ‪1433/4/6‬ه ـ اســتناد ًا‬\n‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة أنــه بتاريــخ ‪1433/4/4‬ه ـ قبــض‬\n‫عليــه مــن قبــل الضبــط االداري مبحافظــة جــدة حليازتــه يف جيــب بنطالــه‬\n‫األميــن الســفلي كيســا بداخلــه عــدد(‪ )361‬ثالثمائــة وواحــد وســتني‬\n\n                                                                                      ‫‪318‬‬\n\f      ‫حبــة بيضــاء اللــون ‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي رقــم‪.........‬‬\n      ‫لعــام ‪1433‬ه ـ احتــواء عينــة احلبــوب املضبوطــة واملرســلة للتحليــل علــى‬\n      ‫مــادة األمفيتامــن املؤثــرة عقلي ـ ًا املدرجــة باجلــدول رقــم(‪ )2‬فئــة (ب)‬\n      ‫امللحــق بنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وباســتجواب‬\n      ‫املدعــى عليــه‪ ........‬أقــر بحيــازة (‪ )361‬ثالثمائــة وواحــد وســتني حبــة‬\n      ‫مؤثــرة عقلي ـ ًا بقصــد التعاطــى وأنــه تعاطــى مــن الكميــة املضبوطــة‬\n      ‫وأنــه يتعاطــى نوعهــا مــن الســابق وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n      ‫إلــى املدعــى عليــه ‪ ،.........‬بحيــازة (‪ )361‬ثالثمائــة وواحــد وســتني‬\n      ‫حبــة حتتــوي علــى مــادة اإلمفيتامــن املؤثــرة عقلي ـ ًا بقصــد الترويــج‬\n      ‫والتعاطــي وتعاطيــه مــن ذات الكميــة ولنوعهــا مــن الســابق وذلــك‬\n      ‫لألدلــة والقرائــن املذكــوره بالئحــة الدعــوى (وبالبحــث عــن ســوابقه‬\n      ‫عثــر لــه علــى ســابقة حيــازة املخــدرات) وحيــث إن مــا أقــدم عليــه املدعــى‬\n      ‫عليــه مــن األفعــال احملرمــة شــرع ًا واملجرمــة نظامـ ًا طبقــا للمــادة الثالثــة‬\n      ‫الفقــرة (‪ )2‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم م‪ 39/‬وتاريــخ ‪1426/7/8‬ه ـ واملعاقــب عليهــا‬\n      ‫وفقـ ًا للمادتــن(‪ )41.38‬مــن نظــام مكافحــة املخــدرات املشــار اليــه مــع‬\n      ‫مراعــاة مــا ورد باملادة(‪)62‬مــن ذات النظــام ‪ ،‬أطلــب إثبــات مــا أســند‬\n      ‫إليــه ومعاقبتــه بالعقوبــات األصليــة والتكميليــة التاليــة ‪-1 -:‬بالســجن‬\n      ‫واجللــد والغرامــة اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬من نظام مكافحة‬\n      ‫املخــدرات املشــار إليــه‪ -2 0‬إبعــاده عــن البــاد وفقــا للفقــرة (‪ )2‬من املادة‬\n      ‫(‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه هكــذا أدعــى وجــرى‬\n      ‫ا‬\n      ‫إحضــار املدعــى عليــه وبســؤال املدعــى عليــه عــن الدعــوى أجــاب قائـ ً‬\n      ‫ا فقــد قبــض علـ ّـي‬  ‫كل مــا ذكــره املدعــي العــام صحيــح جملــة وتفصيـ ً‬\n\n\n‫‪319‬‬\n\f‫وبحوزتــي عــدد (‪ )361‬حبــة حتتــوي علــى االمفيتامــن احملظــور واملؤثــر‬\n‫عقلي ـ ًا وذلــك لقصــد الترويــج والتعاطــي لهــا ومــا ذكــره املدعــي العــام‬\n‫مــن أننــي تعاطيــت منهــا لنوعــه ســابقا فذلــك صحيــح أيضــا ومــا ذكــره‬\n‫املدعــي العــام مــن وجــود عــدد ســابقة واحــدة يف املخــدرات مســجلة علـ ّـي‬\n‫فصحيــح أيضــا وقــد أقدمــت علــى ذلــك وأنــا مســلم وأعلــم بــان ذلــك‬\n‫محــرم شــرع ًا ومجــرم نظام ـ ًا وأنــا تائــب إلــى اهلل عــز وجــل ونــادم علــى‬\n‫هــذا الفعــل وأتعهــد بعــدم العــودة لفعلــي هكــذا أجــاب هــذا وقــد جــرى‬\n‫اطالعــي علــى أوراق املعاملــة وعلــى التقريــر الكيميائــي الشــرعي رقــم‬\n‫(‪ 1303‬ك م ش) املرفــق باملعاملــة لفــة رقــم (‪ )38‬ويتضمــن إيجابيــة‬\n‫احتــواء العينــة لالمفيتامــن احملظــور واملؤثــر عقلي ـ ًا كمــا جــرى‬\n‫اطالعــي علــى صحيفــة ســوابق املدعــى عليــه املرفقــة باملعاملــة باللفــة‬\n‫رقــم (‪ )32‬املتضمنــة وجــود ســابقة واحــدة مســجلة علــى املدعــى عليــه‬\n‫يف حيــازة املخــدرات فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا‬\n‫قــرره الطرفــان وملــا تضمنــه التقريــر الكيميائــي الشــرعي املنــوه عنــه‬\n‫بعاليــة فلمــا ســبق فقــد ثبــت لــدي إدانــة املدعــى عليــه املذكــور بعاليــه‬\n‫مبــا نســب إليــه مــن حيازتــه لعــدد (‪ )361‬ثالثمائــة وواحــدة وســتون حبــة‬\n‫مــن احلبــوب احملتويــة علــى االمفيتامــن احملظــور واملؤثــر عقليـ ًا لقصــد‬\n‫الترويــج والتعاطــي لهــا وتعاطيــه لنوعــه ومنهــا ســابق ًا ومبــا أن مــا قــام‬\n‫قبيحــا وجــرأة يف الباطــل‬  ‫ً‬     ‫ا‬\n                                   ‫محرمــا وفع ـ ً‬\n                                              ‫ً‬     ‫ا‬‫بــه املدعــى عليــه يعــد عم ـ ً‬\n‫يســتحق العقــاب عليــه ملــا يف تعاطــي وترويــج تلــك الســموم مــن إضــرار‬\n‫بنفــس اإلنســان وعقلــه والواجــب عليــه حفظهمــا ونشــر للفســاد أوســاط‬\n‫املجتمــع وذلــك مــن التعــاون علــى اإلثــم والعــدوان واهلل ســبحانه وتعالــى‬\n‫يقــول (وتعاونــوا علــى البــر والتقــوى وال تعاونــوا علــى اإلثــم والعــدوان)‬\n\n\n                                                                                         ‫‪320‬‬\n\f      ‫والشــريعة اإلســامية جــاءت بحفــظ الضروريــات اخلمــس ومنهــا حفــظ‬\n      ‫النفــس والعقــل والنتشــار هــذه احملظــورات أوســاط املجتمــع وهــذا‬\n      ‫يســتوجب األخــذ علــى مــن يقــوم بترويجها بحزم وتطبيــق املادة رقم (‪)38‬‬\n      ‫مــن نظــام مكافحــة املخــدرات املشــار إليــه ال ســيما مــع كبــر الكميــة‬\n      ‫ووجــود ســابقة مخــدرات مســجلة عليــه ومبــا أن املدعــى عليــه أظهــر‬\n      ‫التوبــة والنــدم والعــزم علــى عــدم العــودة لفعلــه ونظــر ًا لكــون الســابقة‬\n      ‫املســجلة علــى املدعــى عليــه يف احليــازة وهــذا يخفــف عنــه العقوبــة وفقــا‬\n      ‫للمــادة رقــم (‪ )60‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ولكــون‬\n      ‫املدعــى عليــه أجنبــي وال فائــدة مــن إطالــة ســجنه إذ مالــه إلــى الترحيــل‬\n      ‫طبقــا‬\n         ‫وذلــك كلــه أمــر يلحــظ ولكــون املدعــى عليــه يســتحق العقوبــة ً‬\n      ‫ووفقــا للمــواد (‪ )53 -56 -60‬مــن نظــام مكافحــة‬      ‫ً‬     ‫للقواعــد الشــرعية‬\n      ‫املخــدرات فلمــا ســبق فقــد حكمــت علــى املدعــى عليــه تعزيــر ًا مبــا يلــي‪:‬‬\n      ‫أوالً‪ :‬يســجن املدعــى عليــه ملــدة أربــع ســنوات يحتســب منهــا مــا أمضــاه‬\n      ‫موقوفــا يف هــذه القضيــة ويجلــد خمســن جلــدة مكــررة عليــه خمســة‬       ‫ً‬\n      ‫عشــر مــرة بينهــن مــدة ال تقــل عــن خمســة أيــام ويدفــع غرامــة ماليــة‬\n      ‫قدرهــا ثالثــة أالف ريــال وفقــا للمــادة رقــم (‪ )60‬مــن النظــام املشــار‬\n      ‫إليــه املتضمنــة حــق النــزول عــن مقتضــى املــادة رقــم (‪ )38‬مــن النظــام‬\n      ‫املشــار إليــه‪ .‬ثاني ـاً‪ :‬يبعــد املدعــى عليــه خــارج اململكــة وال يســمح لــه‬\n      ‫بالعــودة إليهــا إال وفــق تعليمــات احلــج والعمــرة وفقــا للفقــرة رقــم (‪ )2‬مــن‬\n      ‫املــادة رقــم (‪ )56‬مــن نظــام مكافحــة املخــدرات املشــار إليــه ثالثـاً‪ :‬يجلــد‬\n      ‫املدعــى عليــه تســعة وســبعون جلــدة دفعــة واحــدة لقــاء تعاطيــه للحبــوب‬\n      ‫احملظــورة وبعــرض احلكــم علــى الطرفــن قــرر املدعــي العــام معارضتــه‬\n      ‫علــى احلكــم مــع تقــدمي الئحــة اعتراضيــة عليــه فأفهمتــه باحلضــور يف‬\n\n\n‫‪321‬‬\n\f‫يــوم الســبت املوافــق ‪1433/7/26‬ه ـ الســتالم نســخة مــن قــرار احلكــم‬\n‫لتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يومــا اعتبــار ًا مــن التاريــخ‬\n‫املشــار إليــه فــان مضــت املــدة ولــم يقــدم اعتراضــه عليــه خاللهــا فــان‬\n‫حقــه يف تقــدمي الئحــة االعتــراض يكــون ســاقط ًا وفق ـ ًا للمــادة رقــم‬\n‫(‪ )194‬مــن نظــام اإلجــراءات اجلزائيــة كمــا قــرر املدعــى عليــه قناعتــه‬\n‫بــه وجــرى النطــق باحلكــم يف يــوم الثالثــاء املوافــق ‪1433/7/15‬ه ـ‬\n‫الســاعة ‪ 09 : 30‬وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل‬\n                                                       ‫وســلم علــى نبينــا محمــد‪.‬‬\n‫ـاء‬\n  ‫ويف يــوم الثالثــاء ‪1433/9/12‬ه ـ الســاعة ‪ 11 : 45‬فتحــت اجللســة بنـ ً‬\n‫علــى انتهــاء مــدة االعتــراض علــى احلكــم حيــث جــرى إفهــام املدعــي‬\n‫العــام باســتالمه نســخة مــن احلكــم وأنــه ســوف حتتســب مهلــة الثالثــن‬\n‫يومـ ًا لالعتــراض اعتبــار ًا مــن تاريخــه وحيــث انتهــت املــدة املقــررة نظامـ ًا‬\n‫ولــم يتقــدم املدعــي العــام باالســتالم ولــم يتقــدم بالئحــة اعتراضيــة لــذا‬\n‫فقــد قــررت رفــع احلكــم حملكمــة االســتئناف حســب املتبــع وحتــى ال‬\n       ‫يخفــى جــرى إثباتــه واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد ‪،،‬‬\n‫احلمــد هلل والصــاة والســام علــى مــن النبــي بعــده وبعــد ‪ ،‬فقــد جــرى‬\n‫منــا نحــن قضــاة الدائــرة اجلزائيــة الســابعة مبحكمــة االســتئناف يف‬\n‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بجــدة املســاعد رقــم ‪ 33847511‬وتاريــخ‬\n‫‪1434/1/13‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة الشــيخ‪........./‬‬\n‫القاضــي باحملكمــة اجلزائيــة بجــدة رقــم ‪ 33409577‬وتاريــخ‬\n‫‪1433/9/12‬ه ـ احملكــوم فيــه مبــادون بباطــن القــرار املتضمــن دعــوى‬\n‫املدعــى العــام ضد‪........./‬مينــي اجلنســية ‪ 41‬املتهــم يف ومخــدرات بدراســة‬\n\n\n                                                                                         ‫‪322‬‬\n\f      ‫القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم باألكثريــة ‪،‬‬\n      ‫واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪323‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"9e4e6266-eef8-5a22-8ff7-8c53783dbebf","source_page_start":317,"source_page_end":323,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1a92bb68e4b56dac69cbabdfe3b112ffd4d521f82b6be9a7ae3f64be2f618816","normalized_text_hash":"aada1ed90b30e24812d3370dc6c298c824c9e4eb2d3a420a3f02ca14b895c939","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v19-p317-33409577"},{"id":"f5e6d52a-4119-5438-9597-99e84339dc53","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج وتستر على مصدرها -هروب من رجال األمن -بينة غير موصلة -عدم ثبوت الدعوى -تعزير للتهمة القوية.","document_number":"33374012","case_number":"33344796","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/08/11","year":"1434","subject":"مخدرات -حيازة حشيش وحبوب محظورة بقصد الترويج وتستر على مصدرها -هروب من رجال األمن -بينة غير موصلة -عدم ثبوت الدعوى -تعزير للتهمة القوية.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33374012:‬تاريخه‪1433/08/11 :‬هـ‬\n                     ‫رقم الدعوى‪33344796:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 33374012‬تاريخه‪1434/08/11:‬هـ‬\n\n\n ‫مخــدرات‪ -‬حيــازة حشــيش وحبــوب محظــورة بقصــد الترويــج وتســتر‬\n ‫علــى مصدرهــا‪ -‬هــروب مــن رجــال األمــن‪ -‬بينــة غيــر موصلــة‪ -‬عــدم‬\n                               ‫ثبــوت الدعــوى‪ -‬تعزيــر للتهمــة القويــة‪.‬‬\n\n\n\n\n                                                         ‫األصل براءة الذمة‪.‬‬\n\n\n\n\n ‫دعــوى جزائيــة عامــة ضــد املدعــى عليــه تتضمــن طلــب إثبــات إدانتــه‬\n ‫بحيــازة احلشــيش املخــدر وحبــة مــن احلبــوب احملظــورة بقصــد الترويــج‬\n ‫وتســتره علــى مصــدر املخــدر وهروبــه مــن رجــال األمــن‪ ،‬واحلكــم‬\n ‫عليــه بعقوبــة الســجن واجللــد والغرامــة واملصــادرة واملنــع مــن الســفر‬\n ‫طبقــا لنظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبعقوبــة تعزيريــة‬\n ‫علــى باقــي التهــم‪ ،‬مت العثــور علــى ســيارة مرتطمــة بإحــدى الســيارات‬\n ‫وهــي بوضــع التشــغيل بعــد أن قــام قائدهــا بالهــروب مــن رجــال‬\n ‫األمــن وبتفتيشــها عثــر فيهــا علــى احلشــيش املخــدر وحبــة مــن احلبــوب‬\n ‫احملظــورة‪ ،‬أثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة‬\n ‫للحشــيش املخــدر واإلمفيتامــن‪ ،‬أنكــر أمــام احملكمــة مــا أســنده‬\n ‫إليــه املدعــي العــام ودفــع بــأن الســيارة املســتأجرة التــي ضبطــت فيهــا‬\n\n                                                                                   ‫‪324‬‬\n\f      ‫املخــدرات قــد ســرقت منــه‪ ،‬لــم يقــدم املدعــي العــام بينــات كافيــة‬\n      ‫تثبــت مــا أنكــره املدعــى عليــه‪ ،‬قضــت احملكمــة بعــدم إدانــة املدعــى‬\n      ‫عليــه مبــا نســب إليــه وردت دعــوى املدعــي العــام مبعاقبتــه وفــق نظــام‬\n      ‫مكافحــة املخــدرات وقــررت االكتفــاء مبــدة توقيفــه الســابقة لوجــود‬\n      ‫الشــبهة يف نســيانه مفاتيــح الســيارة عليهــا وأنهــا لــم تتعــرض للكســر‬\n      ‫كمــا قــررت مصــادرة املضبوطــات التــي أقــر بعــدم عائديتهــا لــه‪ ،‬قنــع‬\n      ‫املدعــى عليــه باحلكــم وعــارض املدعــي العــام عليــه‪ ،‬قــررت محكمــة‬\n                      ‫االســتئناف املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33344796‬وتاريــخ ‪ 1433/05/18‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 33940404‬وتاريــخ ‪ 1433/05/18‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪ 1433/05/25‬ه ـ افتتحــت اجللســة الســاعة ‪12 :16‬‬\n      ‫وفيهــا قــدم املدعــي العــام دعــواه علــى‪ ، ........‬البالــغ مــن العمــر (‪)37‬‬\n      ‫عام ـاً‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬متــزوج ‪،‬‬\n      ‫متعلم‪،‬موظــف قطــاع خــاص‪ ،‬يقيــم مبدينــة (‪ ، ).....‬أوقــف بتاريــخ‬\n      ‫‪1433/4/3‬ه ـ ‪ ،‬وأحيــل إلــى شــعبة ســجن امللــز مبوجــب أمــر اإلحالــة‬\n      ‫ومت ــديد التوقيف رقــم (هـ ر‪ ) 40909 / 5/1‬وتاريخ ‪1433/4/8‬هـ وفق ًا‬\n      ‫للقــرار الــوزاري رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ املبنــي علــى املــادة‬\n      ‫(‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة‪ .‬قائــا يف دعــواه عليــه إنـ ــه بتاريــخ‬\n      ‫‪1433/3/8‬ه ـ ش ــاهـ ــدت إحـ ــدى فـ ــرق دوريـ ــات األمـ ـ ــن سي ـ ـ ــارة مـ ــن‬\n\n‫‪325‬‬\n\f‫نـ ـ ــوع (‪ ).......... ...‬حتمــل اللوحــة رقــم (‪ )............‬علــي طريــق (‪).............‬‬\n‫يســتقلها شــخص وعنــد مشــاهدته الفرقــة ارتكــب الفــرار إلــى داخــل‬\n‫احلــي فتمــت متابعتــه حتــى مت العثــور علــى الســيارة مرتطمــة بإحــدى‬\n‫الســيارات املتوقفــة بداخــل احلــي وكانــت الســيارة بوضــع التشــغيل‬\n‫وارتكــب قائدهــا الفــرار وبتفتيــش الســيارة عثــر أمــام مقعــد املرافــق‬\n‫علــى قطعــة بحجــم البالطــة يشــتبه أن تكــون مــن احلشــيش املخــدر تــزن‬\n‫(‪ )388,2‬ثالثمائــة وثمانيــة وثمانــن جرامـ ًا وعشــري اجلــرام كمــا عثــر‬\n‫علــى شــنطة صغيــرة بداخلهــا قطعــة يشــتبه أن تكــون مــن احلشــيش‬\n‫املخــدر تــزن (‪ )34,2‬أربعــة وثالثــن جرام ـ ًا وعشــري اجلــرام كمــا عثــر‬\n‫علــى ثالثــة أكيــاس تفــوح منهــا رائحــة يشــتبه أن تكــون مــن احلشــيش‬\n‫املخــدر وكذلــك (‪ )1‬حبــة واحــدة حتمــل عالمــة الكبتاجــون احملظــور‬\n‫كمــا عثــر علــى مبلــغ مالــي قــدره (‪ )2400‬ألفــن وأربعمائــة ريــال و(‪)5‬‬\n‫خمســة جــواالت ( مت طلــب حجزهــا متهيــد ًا لطلــب مصادرتهــا مبوجــب‬\n‫اخلطــاب رقــم (ه ـ ر‪ )54218/5/1‬وتاريــخ ‪1433/5/11‬هــ) كمــا عثــر‬\n‫معــه علــى جهــاز جــوال نــوع (‪( ).....‬مت رده لــه مبوجــب اخلطــاب رقــم (ه ـ ر‬\n‫ا للمصادرة‬      ‫‪ )54351 /5/1‬وتاريــخ ‪1433/ 5 /11‬هــ) كونــه ليــس محـ ً‬\n‫اســتناد ًا إلــى املــادة (‪ )86‬مــن نظــام اإلجــراءات اجلزائيــة)‪ .‬وبتاريــخ‬\n‫‪1433/4/3‬ه ـ ســلم املذكــور نفســه ملكافحــة املخــدرات بغــرب (‪.).....‬‬\n‫وقــد أثبــت التقريــر الكيميائــي الشــرعي الصــادر مــن مركــز مراقبــة‬\n‫الســموم والكيميــاء الطبيــة الشــرعية مبدينــة (‪ ).....‬املرفــق رقــم‬\n‫(‪/2799‬س) لعــام ‪1433‬ه ـ ايجابيــة عينتــي القطعتــن املضبوطتــن‬\n‫وغســالة األكيــاس املضبوطــة للحشــيش وهــو مــن املــواد املخــدرة‬\n‫املدرجــة باجلــدول (‪ )1‬فئــة (أ) امللحــق بنظــام مكافحــة املخــدرات‬\n\n\n                                                                                               ‫‪326‬‬\n\f      ‫واملؤثــرات العقليــة‪ .‬واحتــواء احلبــة املضبوطــة لإلمفيتامــن وهــو مــن‬\n      ‫املــواد املنبهــة املدرجــة باجلــدول رقم (‪ )2‬فئة (ب) امللحق بنظام مكافحة‬\n      ‫املخــدرات واملؤثــرات العقليــة‪ .‬وقــد أســفرت إجــراءات التحقيــق عــن‬\n      ‫توجيــه االتهــام لـ ـ ‪ /‬بحيــازة قطعتني من احلشــيش املخــدر تزنان (‪)422,4‬‬\n      ‫أربعمائــة واثنــان وعشــرين جرامـ ًا وأربعــة أعشــار اجلــرام وثالثــة أكيــاس‬\n      ‫حتتــوي غســالتها علــى احلشــيش املخــدر و(‪ )1‬حبــة واحــدة مــن حبــوب‬\n      ‫اإلمفيتامــن املنبهــة احملظــورة بقصــد الترويــج املجــرم مبوجــب املــادة‬\n      ‫(الثالثــة) مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n      ‫باملرســوم امللكــي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ وتســتره علــى‬\n      ‫مصــدر مــا ضبــط وهربــه مــن الفرقــة القابضــة املعاقــب على ذلك شــرعاً‪.‬‬\n      ‫وذلــك لألدلــة والقرائــن التاليــة‪ -1 :‬مــا تضمنــه محضــر القبــض املنــوه‬\n      ‫عنــه املرفــق لفــة رقــم ( ‪-2 .)1‬مــا تضمنــه التقريــر الكيميائــي الشــرعي‬\n      ‫املنــوه عنــه املرفــق لفــة رقــم ( )‪ .‬وببحــث ســوابقه اتضــح عــدم وجــود‬\n      ‫ســوابق مســجلة عليــه حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب إثبــات إدانتــه مبــا‬\n      ‫أســند إليــه واحلكــم عليــه باآلتــي‪ .1 :‬بعقوبــة الســجن واجللــد والغرامــة‬\n      ‫املاليــة وفقــا للفقــرة (األولــى) مــن املــادة (‪ )38‬مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة لقــاء مــا أســند إليــه‪ .‬وتشــديد العقوبــة عليــه‬\n      ‫وفقـ ًا للفقــرة (ج) بنــد (ثانيـاً) مــن نفــس املــادة املشــار إليهــا‪.2 .‬منعــه مــن‬\n      ‫الســفر إلــى خــارج اململكــة بعــد انتهــاء تنفيــذ عقوبة ســجنه وفقـ ًا للفقرة‬\n      ‫(األولــى) مــن املــادة (‪ )56‬مــن نفــس النظــام املشــار إليه‪.3.‬مصــادرة‬\n      ‫الهواتــف احملمولــة وعددهــا (‪ )5‬خمســة هواتــف أربعــة منهــا مــن نــوع‬\n      ‫(‪ ).....‬و هاتــف واحــد (‪ )1‬مــن نــوع (‪ ).....‬الســتخدامها يف اجلرميــة وفقــا‬\n\n\n‫‪327‬‬\n\f‫مصــادرة املبلــغ املضبــوط قــدره (‪ )2400‬ألفــن وأربعمائــة ريــال كونــه‬\n‫نــاجت مــن االجتــار باملخــدرات وفقــا للفقــرة ( الثانيــة) مــن املــادة (‪ )53‬مــن‬\n‫النظــام املشــار إليــه‪ .5.‬بعقوبــة تعزيريــة بحقــه لقــاء تســتره علــى مصــدر‬\n‫مــا ضبــط ولقــاء هربــه مــن الفرقــة القابضــة‪ .‬وبــاهلل التوفيــق ‪ ،‬وبتــاوة‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه ســعودي بالبطاقــة رقــم (‪).....‬‬\n‫أجــاب بقولــه مــا جــاء يف دعــوى املدعــي العــام كلــه غيــر صحيــح فأنــا ال‬\n‫عالقــة لــي باملضبوطــات املمنوعــة املذكــورة يف الدعــوى مطلقــا وكل‬\n‫مــا يف األمــر أنــي اســتأجرت ســيارة مــن أحــد مكاتــب التأجيــر ونســيت‬\n‫مفاتيــح الســيارة علــى البــاب اخلارجــي ودخلــت منزلــي يف حــدود الســاعة‬\n‫الثامنــة والنصــف وملــا خرجــت صبــاح الغــد للذهــاب للــدوام لــم أجــد‬\n‫الســيارة فقمــت بإبــاغ مكتــب التأجيــر ومــن ثــم قــام بإرســال منــدوب‬\n‫لــي وقمنــا بإبــاغ اجلهــات األمنيــة بذلــك ومــن ثــم ذهبــت لعملــي هكــذا‬\n‫أجــاب ثــم جــرى ســؤاله عــن ســبب عــدم تســليم نفســه للجهــات األمنيــة‬\n‫مباشــرة فأجــاب قائــا إننــي يف نفــس اليــوم الــذي جــرى إبــاغ اجلهــات‬\n‫األمنيــة بســرقة الســيارة اتصــل بــي مكتــب التأجير وطلــب مني مراجعة‬\n‫مكتــب مكافحــة املخــدرات يف غــرب الريــاض وكان ذلــك يــوم‬\n‫األربعــاء فذهبــت لهــم يــوم الســبت فقابلــت الرائــد (‪ ).....‬وكذلــك رئيــس‬\n‫التحقيقــات فطلبــت منهــم رفــع البصمــات ثــم أخبرتهــم بــأن زوجتــي يف‬\n‫املستشــفى يف وضــع إجهــاض وطلبــوا منــي الذهــاب لالطمئنــان عليهــا‬\n‫ومــن ثــم راجعنــا ومــن ثــم راجعتهــم بعــد أســبوع وأخبرتهــم بــأن زوجتــي‬\n‫أجهضــت وطلبــوا منــي إنهــاء موضــوع عملــي وتســليم العهــدة ألنــه ســيتم‬\n‫إيقــايف فرجعــت لعملــي وأنهيــت أعمالــي لكونــي أعمل مديــرا للعالقات‬\n\n\n                                                                                         ‫‪328‬‬\n\f      ‫احلكوميــة يف (‪ ).....‬وقدمــت علــى إجــازة ملــدة أســبوعني ومــن ثــم ســلمت‬\n      ‫نفســي هكــذا أجــاب‪ .‬وبعــرض ذلــك علــى املدعــي العــام أجــاب بقولــه‬\n      ‫أطلــب الرجــوع للمعاملــة لالطــاع علــى مــا جــاء فيهــا مــن أدلــة وقرائــن‬\n      ‫ورفعــت اجللســة لدراســة القضيــة بعــد أن حــدد لهــا موعــدا يــوم االثنــن‬\n      ‫‪1433/6/2‬ه ـ وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آله‬\n      ‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1433/05/25‬ه ـ ويف يــوم الســبت‬\n      ‫‪1433/6/14‬ه ـ افتتحــت اجللســة الثانيــة الســاعة العاشــرة وفيهــا حضــر‬\n      ‫املدعــي العــام وحضــر حلضــوره املدعــى عليــه وبالرجــوع للمعاملــة وجــد‬\n      ‫فيهــا لفــة رقــم‪ 12‬أنــه عثــر يف الســيارة العائــدة للمدعــى عليــه عنــد‬\n      ‫تفتيشــها علــى خمســة جــواالت وجهــاز (‪ ).....‬وجهــاز كمبيوتــر محمــول‬\n      ‫وجهــاز هاردســك وأربــع شــرائح اتصــال‪ .‬وبعــرض ذلــك علــى املدعــى‬\n      ‫عليــه أجــاب بقولــه إن الــذي يخصنــي مــن املضبوطــات املذكــورة هــو‬\n      ‫جهــاز الكمبيوتــر احملمــول وجهــاز اآليفــون وجهــاز الهاردســك فقــط‬\n      ‫أمــا باقــي األجهــزة والشــرائح فــا تعــود لــي وال علــم لــي بهــا مطلق ـ ًا‬\n      ‫هكــذا أجــاب‪ .‬ثــم جــرى االطــاع علــى أنــواع األجهــزة اخلمســة وهــي‬\n      ‫كاآلتــي ‪ _1‬جــوال (‪ _2 ).....‬جــوال (‪ _3 ).....‬جــوال (‪ _4 ).....‬جــوال‬\n      ‫(‪ _5 ).....‬جــوال (‪ .).....‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه إن‬\n      ‫هــذه االجهــزة ال تعــود لــي مطلقـ ًا ولــم يســبق أن اســتخدمتها أو اتصلــت‬\n      ‫بهــا هكــذا أجــاب‪ .‬وكــذا وجــد يف املعاملــة محضــر القبــض لفــة رقــم‪1‬‬\n      ‫واملتضمــن العثــور علــى الســيارة العائــدة للمدعــى عليــه وجــد بداخلهــا‬\n      ‫أمــام مقعــد املرافــق بالطــة حشــيش تــزن ‪ 388,2‬جــرام وقطعــة حشــيش‬\n      ‫أخــرى بداخــل شــنطة صغيــرة اللــون ســوداء تــزن ‪ 34,2‬جــرام ووجــد‬\n      ‫بداخــل الشــنطة كذلــك علــى حبــة واحــدة كبتاجــون وعــدد أربــع‬\n\n\n‫‪329‬‬\n\f‫شــرائح جــوال وعــدد ســت جــواالت أحدهــم (‪ ).....‬وجهــاز الب تــوب‬\n‫وجهــاز هاردســك ووجــد يف املقعــد اخللفــي بدلة عســكرية تابعة للحرس‬\n‫الوطنــي ومبلــغ ألفــن وأربعمائــة ريــال وعقــد تأجيــر الســيارة صــادر مــن‬\n‫مكتــب (‪.... / ).....‬الــخ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه‬\n‫مــا يتعلــق باألجهــزة واملخــدرات فقــد أجبــت عمــا يخصهــا أمــا مــا يتعلــق‬\n‫ببدلــة احلــرس الوطنــي فــا علــم لــي بهــا وأنــا لســت عســكريا وإمنــا أعمل‬\n‫يف احــد (‪ ).....‬وال يوجــد أحــد مــن اشــقائي أو اصدقائــي يعمــل يف احلرس‬\n‫الوطنــي علم ـ ًا بــأن جهــاز (‪ ).....‬لــم يكــن يف شــنطة الــاب تــوب وإمنــا‬\n‫كان يف درج الســيارة وشــنطة الــاب تــوب كانــت يف الشــنطة اخللفيــة‬\n‫للســيارة هكــذا أجــاب فعليــه ولكونــه عنــد تصفــح املعاملــة لــم يظهــر‬\n‫بأنــه جــرى التحــري عــن أجهــزة اجلــواالت املضبوطــة وشــرائح االتصــال‬\n‫وهــل هــي تخــص املدعــى عليــه أو صــدر منهــا اتصــاالت منــه أو إليــه‬\n‫وكــذا لــم يظهــر بأنــه جــرى معرفــة اصحــاب الشــرائح بواســطة شــركة‬\n‫االتصــاالت التابعــة لهــا‪ .‬وحيــث إن هــذه االمــور مؤثــرة يف القضيــة فقــد‬\n‫تقــرر رفــع اجللســة للكتابــة لهيئــة التحقيــق واالدعــاء العــام إلكمــال‬\n‫الــازم حيــال ذلــك والــى حــن ورود جــواب منهــم بذلــك واهلل املوفــق‬\n‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬ويف يــوم االحــد ‪1433/7/27‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى‬\n‫عليــه وقــد عــادت املعاملــة مــن هيئــة التحقيــق واالدعــاء العــام برقــم‬\n‫‪ 79081‬يف ‪1433/7/22‬ه ـ وبرفقهــا محضــر تفريــغ املكاملــات الهاتفيــة‬\n‫املــدون بدفتــر التحقيــق لفــة رقــم‪ 29‬ص‪ 4‬ونــص احلاجــة منــه‪ :‬بصفتــي‬\n‫عضــو هيئــة التحقيــق واالدعــاء العــام مبنطقــة (‪ ).....‬احملقــق ‪).....( /‬‬\n‫فقــد جــرى االطــاع علــى القــرص املدمــج الــوارد مــن مكافحــة‬\n\n\n                                                                                    ‫‪330‬‬\n\f      ‫املخــدرات بغــرب (‪ ).....‬احملتــوي علــى االتصــاالت الصــادرة والــواردة مــن‬\n      ‫ارقــام الشــرائح املضبوطــة بداخــل ســيارة املتهــم وتبــن ان ارقامهــا (‪).....‬‬\n      ‫وجميعهــا بأســماء مختلفــة مــا عــدا الرقــم االخيــر فهــو باســم املتهــم‬\n      ‫املذكــور وهــو الــذي كان بداخــل جهــاز (‪ ).....‬الــذي افــاد املتهــم بانــه‬\n      ‫عائــد لــه وبتدقيــق االتصــاالت الصــادرة والــواردة مــن تلــك الشــرائح‬\n      ‫بينهــا وبــن الرقــم االخيــر العائــد للمتهــم تبــن عــدم وجــود اي اتصــاالت‬\n      ‫صــادرة او واردة بينهــا كمــا مت تدقيــق االتصــاالت بــن تلــك الشــرائح‬\n      ‫والرقــم الــذي ذكــره املتهــم عنــد تدويــن بياناتــه الشــخصية عنــد‬\n      ‫اســتجوابه وهــو تبــن عــدم وجــود اي اتصــاالت بينهــا أ هــ‪ .‬وبالرجــوع‬\n      ‫للمعاملــة وجــد فيهــا لفــة رقــم‪ 38‬محضــر التعــرف واملتضمــن بانــه ال‬\n      ‫ميكــن التعــرف علــى قائــد الســيارة لكونــه لــم تتــم مشــاهدته الختفائــه‬\n      ‫بعــد هروبــه والعثــور علــى الســيارة داخــل احلــي أ هــ‪ .‬كمــا وجــد فيهــا‬\n      ‫التقريــر الكيميائــي الشــرعي رقــم ‪/2799‬س واملتضمــن ايجابيــة املــواد‬\n      ‫املرســلة ملــادة احلشــيش املخــدر أ هــ‪ .‬فبنــاء علــى مــا تقــدم مــن دعــوى‬\n      ‫املدعــي العــام وحيــث انكــر املدعــى عليــه مــا جــاء يف دعــوى املدعــي‬\n      ‫العــام وحيــث قــرر املدعــى عليــه بــان ســيارته تعرضــت للســرقة وحيــث ان‬\n      ‫املضبوطــات التــي وجــدت داخــل الســيارة اتضــح بــان بعضهــا ال عالقــة‬\n      ‫للمدعــى عليــه بهــا ومــن ذلــك شــرائح االتصــاالت واجهــزة اجلــوال وكــذا‬\n      ‫البدلــة العســكرية وحيــث ان مــا يف اوراق املعاملــة ال يديــن املدعــى‬\n      ‫عليــه بحيازتــه املضبوطــات املذكــورة وكــذا ال يثبــت عائديتهــا لــه وملــا‬\n      ‫جــاء يف محضــر التعــرف املذكــور مضمونــه بعاليــه فعليــه فلــم يثبــت‬\n      ‫لــدي حيــازة املدعــى عليــه للمخــدرات املذكــورة يف دعــوى املدعــي العــام‬\n      ‫ورددت طلــب املدعــي العــام بطلــب معاقبــة املدعــى عليــه وفــق للفقــرة‬\n\n\n‫‪331‬‬\n\f‫االولــى مــن املــادة رقــم ‪ 38‬مــن نظــام مكافحــة املخــدرات وكــذا منعــه‬\n‫مــن الســفر ومصــادرة الهاتــف اجلــوال العائــد لــه مــن نــوع (‪ ).....‬لعــدم‬\n‫ثبــوت موجبــه اال ان الشــبهة ال زالــت متوجهــه ضــد املدعــى عليــه الســيما‬\n‫ان املدعــى عليــه اقــر بانــه نســي مفاتيــح الســيارة عليهــا وانهــا لــم تتعــرض‬\n‫للكســر من قبل ســارقها وقررت تعزيره لقاء الشــبهة وذلك باالكتفاء‬\n‫باملــدة التــي امضاهــا مــن تاريــخ ايقافــه ‪1433/4/3‬ه ـ وبذلــك حكمــت‪.‬‬\n‫وبعرضــه علــى املدعــي العــام قــرر االعتــراض مكتفيــا بالئحــة الدعــوى‬\n‫امــا املدعــى عليــه فقــد قــرر عــدم القناعــة ويطلــب االســتئناف بالئحــة‬\n‫اعتراضيــة وجــرى افهامــه بالتعليمــات‪ .‬واهلل املوفــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد‪ .‬ويف يــوم األحــد ‪1433/8/18‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــى عليــه وقــرر قناعتــه باحلكــم وأنــه ال يرغــب يف‬\n‫تقــدمي الئحــة اعتراضيــة ويطلــب إرفــاق التقاريــر الطبيــة اخلاصــة بزوجتــه‬\n‫والتــي تفيــد بــأن زوجتــه حصــل عليهــا إجهــاض بالتاريــخ املذكــور مــع‬\n‫اوراق املعاملــة هكــذا قــرر فعليــه فقــد أمــرت برفــع املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق اإلجــراء حســب املتبــع واهلل املوفــق وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه اجمعــن‪ .‬ويف يــوم االربعــاء‬\n‫‪1434/5/15‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه وقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫وبرفقهــا القــرار رقــم ‪ 33480114‬يف ‪1433/12/27‬ه ـ ونــص احلاجــة‬\n‫منــه‪ :‬وبدراســة القــرار وصــورة ضبطــه واوراق املعاملــة قررنــا باألكثريــة‬\n‫اعادتهــا ملالحظــة االتــي‪ :‬ممــا اتهــم بــه املدعــى عليــه هروبــه مــن الفرقــة‬\n‫القابضــة وقــد طلــب املدعــي العــام معاقبتــه علــى ذلــك وطلــب املدعــي‬\n‫العــام مصــادرة املبلــغ املضبــوط معــه ولــم جنــد فضيلتــه تعــرض لذلــك‬\n\n\n                                                                                        ‫‪332‬‬\n\f      ‫بشــي يف حكمــه حتــى يكــون احلكــم مشــموال بجميــع طلبــات املدعــي‬\n      ‫العــام‪ .‬واهلل املوفــق‪ .‬أهــ‪ .‬فعليــه اجيــب اصحــاب الفضيلــة بأنــي لــم يثبــت‬\n      ‫لــدي قيــام املدعــى عليــه بالهــروب مــن الفرقــة القابضــة ورددت طلــب‬\n      ‫املدعــي العــام مجازاتــه لقــاء الهــرب مــن الفرقــة امــا مــا يتعلــق باملبلــغ‬\n      ‫املضبــوط ولكــون املدعــى عليــه انكــر عائديــة املبلــغ املضبــوط يف‬\n      ‫ســيارته لــه فقــد امــرت مبصــادرة املبلــغ املضبــوط يف الســيارة وقــدره‬\n      ‫الفــان واربعمائــة ريــال لوجــود الشــبهة القويــة انــه نــاجت مــن عمليــة ترويــج‬\n      ‫املخــدرات وقــام بهــا الشــخص الهــارب مــن الفرقــة القابضــة‪ .‬وبذلــك‬\n      ‫حكمــت‪ .‬وبعرضــه علــى املدعــي العــام قــرر انــه ال زال معترضــا امــا‬\n      ‫املدعــى عليــه فقــد قــرر القناعــة باحلكــم‪ .‬واهلل املوفــق وصلــى اهلل وســلم‬\n                                            ‫على نبينا محمد‪ .‬حرر يف ‪1434/5/15‬هـ‪.‬‬\n      ‫احلمــد اهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n      ‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....( /‬املســجل برقــم‬\n      ‫‪ 33374012‬وتاريــخ ‪1433/8/11‬ه ـ اخلــاص بدعــوى املدعي العام ضد‪/‬‬\n      ‫(‪ ).....‬التهامــه بقضيــة مخــدرات علــى النحــو املوضــح بالقــرار املتضمــن‬\n      ‫حكــم فضيلتــه مبــا هــو مــدون ومفصــل بــه‪ .‬وحيــث ســبق دراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب بــه فضيلتــه‬\n      ‫علــى قــرار الدائــرة رقــم ‪ 33480114‬وتاريــخ ‪1433/12/27‬ه ـ قررنــا‬\n      ‫املصادقــة علــى احلكــم بعــد االجــراء األخيــر ‪ .‬وبــاهلل التوفيــق وصلــى‬\n                                  ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪333‬‬\n\f                       ‫كشاف املوضوعات‬\n\n‫الصفحة‬                       ‫املوضوع‬                        ‫التصنيف‬   ‫م‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n  ‫‪5‬‬                                                          ‫حيازة‬    ‫‪1‬‬\n                   ‫بقصد التعاطي وتعاطيه له‬\n\n\n         ‫دعوى عامة بتعزير املدعى عليهما حليازتهما احلشيش‬\n  ‫‪9‬‬                                                          ‫حيازة‬    ‫‪2‬‬\n                          ‫بقصد التعاطي‬\n\n\n            ‫دعوى عامة بتعزير املدعى عليه حليازته حبوب‬\n  ‫‪16‬‬       ‫الكبتاجون بقصد التعاطي وتعاطيه لها وقيادته‬        ‫حيازة‬    ‫‪3‬‬\n                         ‫السيارة حتت تأثيرها‬\n\n\n          ‫دعوى عامة بإقامة حد املسكر على املدعى عليه‬\n  ‫‪22‬‬      ‫وتعزيره حليازته احلبوب احملظورة واحلشيش بقصد‬       ‫حيازة‬    ‫‪4‬‬\n                       ‫التعاطي وتعاطيه لها‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته الهيروين‬\n  ‫‪30‬‬     ‫بقصد الترويج واالجتار وترويجه يف السابق ومقاومته‬    ‫حيازة‬    ‫‪5‬‬\n           ‫للفرقة القابضة وهروبه منها وتستره على املصدر‬\n\n\n           ‫دعوى عامة بتعزير املدعى عليه حليازته احلشيش‬\n  ‫‪37‬‬       ‫بقصد التعاطي وتعاطيه له واملطالبة بإقامة حد‬       ‫حيازة‬    ‫‪6‬‬\n            ‫املسكر وتعزيره حليازته له بقصد االستعمال‬\n\n\n         ‫دعوى عامة بإقامة حد املسكر على املدعى عليه‬\n  ‫‪45‬‬                                                         ‫حيازة‬    ‫‪7‬‬\n         ‫لتعاطيه احلشيش وتعزيره حليازته وترويجه للحشيش‬\n\n\n            ‫دعوى عامة بتعزير املدعى عليه حليازته حبوب‬\n  ‫‪57‬‬           